      // Безопасные обёртки над localStorage. Причины:
      //  • Safari «Private» и встроенные webview кидают QuotaExceededError даже на первый setItem;
      //  • при большом state (много сделок) JSON может не влезть в квоту (~5 МБ);
      //  • доступ к самому объекту localStorage кидает SecurityError в «песочных» iframe.
      // Раньше это могло уронить поток сохранения. Теперь сбой пишется в консоль и не ломает UI.
      function lsGet(key) {
        try { return localStorage.getItem(key); } catch (e) { console.warn("localStorage.getItem", key, e); return null; }
      }
      function lsSet(key, value) {
        try { localStorage.setItem(key, value); return true; }
        catch (e) { console.warn("localStorage.setItem не удался (квота/приватный режим):", key, e); return false; }
      }
      function lsRemove(key) {
        try { localStorage.removeItem(key); } catch (e) { console.warn("localStorage.removeItem", key, e); }
      }

      // ── Кто последним писал состояние в localStorage ─────────────────────────
      // Обработчики pagehide/beforeunload раньше безусловно писали свой снапшот
      // памяти поверх localStorage. Если приложение открыто в двух местах (вкладка
      // + PWA), закрытие ПЕРВОЙ вкладки затирало правки второй: её состояние в
      // памяти — от момента открытия. На iOS pagehide срабатывает при каждом уходе
      // приложения в фон, так что это не редкий случай.
      // Решение: каждая запись state помечает localStorage случайным токеном.
      // Писать на выгрузке можно только если токен всё ещё наш — иначе кто-то
      // записал свежее, и наш снапшот заведомо устарел.
      const LS_REV_KEY = "adervis_ls_rev";
      let _myLsRev = null;
      function _bumpLsRev() {
        _myLsRev = "rev_" + Date.now().toString(36) + Math.random().toString(36).slice(2, 10);
        lsSet(LS_REV_KEY, _myLsRev);
      }
      function _ownsLsState() {
        return !!_myLsRev && lsGet(LS_REV_KEY) === _myLsRev;
      }

      // ── Что мы знаем про облачную копию ──────────────────────────────────────
      // Живёт в localStorage (в отличие от _cloudDirty, который сбрасывается при
      // перезагрузке). Нужен, чтобы после офлайна не затянуть УСТАРЕВШЕЕ облако
      // поверх локальных правок, которые ещё не доехали. Формат:
      //   { agencyId, cloudUpdatedAt, dirty }
      const CLOUD_SYNC_KEY = "adervis_cloud_sync";
      function _getCloudSyncMark() {
        try {
          const raw = lsGet(CLOUD_SYNC_KEY);
          const m = raw ? JSON.parse(raw) : null;
          return m && typeof m === "object" ? m : null;
        } catch (e) { return null; }
      }
      function _setCloudSyncMark(patch) {
        const prev = _getCloudSyncMark() || {};
        lsSet(CLOUD_SYNC_KEY, JSON.stringify({ ...prev, ...patch }));
      }

      function getSupabaseConfig() {
        return {
          url: lsGet("sb_url") || _DEFAULT_SB_URL,
          key: lsGet("sb_key") || _DEFAULT_SB_KEY
        };
      }

      function initSupabase() {
        const { url, key } = getSupabaseConfig();
        if (!url || !key || !window.supabase) { _authChecking = false; renderAuthGateEl(); return; }
        try {
          _supabase = window.supabase.createClient(url, key);
          // Быстрая проверка сохранённой сессии — не показываем auth gate до её результата
          _supabase.auth.getSession().then(({ data: { session } }) => {
            _authChecking = false;
            if (session) { _adminSession = session; _onUserLoggedIn(session); }
            else { renderAuthGateEl(); }
          });
          _supabase.auth.onAuthStateChange((event, session) => {
            // INITIAL_SESSION fires on subscribe and duplicates the getSession() call above
            if (event === "INITIAL_SESSION") return;
            // TOKEN_REFRESHED: only update the session token, do not reload all data
            if (event === "TOKEN_REFRESHED") { _adminSession = session; return; }
            _adminSession = session;
            if (session) { _onUserLoggedIn(session); }
            else {
              _loggedInUserId = null;
              _userProfile = null;
              _onlineUsers = [];
              _briefs = []; _briefsLoaded = false;
              _allPortals = []; _allPortalsLoaded = false;
              if (_realtimeChannel) { _realtimeChannel.unsubscribe(); _realtimeChannel = null; }
              renderAdminTopbar();
              render();
            }
          });
        } catch(e) { _authChecking = false; renderAuthGateEl(); console.warn("Supabase init:", e); }
      }

      /* Цели в Яндекс.Метрике для воронки регистрация → триал → оплата */
      function trackGoal(name, params) {
        try { window.ym && window.ym(109706942, "reachGoal", name, params); } catch(e) {}
      }

      /* ─── Воронка активации ────────────────────────────────────────────────
         регистрация → создана сделка → заполнена смета → отправлено КП.
         Без этих цифр непонятно, на каком шаге отваливаются люди, и правки
         онбординга — угадывание (PLAN.md §4-P0). Цели шлются по одному разу на
         браузер (метка в localStorage): Метрика считает достижения, а не события,
         и десять сохранений одной сделки не должны выглядеть как десять активаций.

         Проверка живёт в save() — единственной точке, через которую проходит любое
         изменение состояния. Так не нужно расставлять вызовы по всем входам в
         создание сделки (их семь) и следить, чтобы новый вход не забыли: класс
         бага «входы рассинхронизированы» в этом файле встречался 7+ раз.

         Побочный эффект, о котором надо помнить при чтении отчётов: у аккаунтов,
         существовавших до этой правки, все три цели сработают при первом же
         сохранении. Считать воронку имеет смысл от даты выката, а не раньше. */
      // dedupeKey нужен там, где цель одна, а объектов много: оплата аванса считается
      // один раз на КАЖДОЕ КП, а не один раз на браузер (см. loadPortalData).
      function _fireGoalOnce(name, dedupeKey) {
        const key = "_goal_" + (dedupeKey || name);
        if (lsGet(key)) return;
        lsSet(key, "1");
        trackGoal(name);
      }

      let _activationGoalsDone = false;
      function _checkActivationGoals() {
        if (_activationGoalsDone || !_adminSession) return;
        // Демо-сделка засеяна нами при регистрации — она не активация пользователя.
        const real = (state.savedProjects || []).filter(p => !p.__demo);
        if (!real.length) return;
        _fireGoalOnce("deal_created");
        if (real.some(p => numberValue(p.total, 0) > 0)) _fireGoalOnce("estimate_filled");
        if (real.some(p => p.portalId)) _fireGoalOnce("proposal_sent");
        if (lsGet("_goal_deal_created") && lsGet("_goal_estimate_filled") && lsGet("_goal_proposal_sent")) {
          _activationGoalsDone = true; // дальше не тратим работу на каждом save()
        }
      }

      /* ── Телеметрия клиентских ошибок ──────────────────────────────────────
         Пишет в public.client_errors (INSERT-only RLS, читает только супер-админ,
         см. migrations/client_errors.sql). Лимит 5 ошибок на сессию, дедупликация
         по тексту. Телеметрия никогда не должна ломать само приложение. */
      let _errReported = 0;
      let _errToastShown = false;
      const _errSeen = new Set();
      function _reportClientError(kind, message, source) {
        try {
          const msg = String(message || "").slice(0, 1000);
          // "Script error." — кросс-доменная ошибка без деталей; ResizeObserver — шум браузера
          if (!msg || msg === "Script error." || msg.includes("ResizeObserver loop")) return;
          const key = msg.slice(0, 120);
          if (_errReported >= 5 || _errSeen.has(key)) return;
          _errSeen.add(key);
          _errReported++;
          if (_supabase) {
            _supabase.from("client_errors").insert({
              kind,
              message: msg,
              source: String(source || "").slice(0, 300),
              url: (location.pathname + location.search).slice(0, 300),
              ua: navigator.userAgent.slice(0, 300),
              agency_id: _adminSession ? getAgencyId() : null
            }).then(() => {});
          }
          if (kind === "error" && !_errToastShown) {
            _errToastShown = true;
            toast("⚠️ Что-то пошло не так. Если приложение работает неправильно — обновите страницу.");
          }
        } catch (e) { /* молча */ }
      }
      window.onerror = (msg, src, line, col, err) => {
        _reportClientError("error", (err && err.stack) || msg, `${src || ""}:${line || 0}:${col || 0}`);
      };
      window.addEventListener("unhandledrejection", (e) => {
        const r = e && e.reason;
        _reportClientError("promise", (r && (r.stack || r.message)) || String(r), "");
      });

      async function _onUserLoggedIn(session) {
        // Один и тот же вход может прийти дважды (событие SIGNED_IN + форс-переход
        // после verifyOtp в VK-входе, либо дубль события от supabase-js) — грузим
        // профиль/облако и поднимаем realtime-канал только раз на пользователя.
        if (_loggedInUserId === session.user.id) return;
        _loggedInUserId = session.user.id;
        _dataLoading = true;
        renderAdminTopbar();
        render();
        try {
          await _loadUserProfile(session.user.id, session.user.email);
          // Сохранить реферальный код, если пользователь пришёл по ref-ссылке
          await _applyReferralCode(session.user.id);
          // Если в браузере данные другого агентства (или нет записи о предыдущем пользователе)
          // — чистим localStorage чтобы новый пользователь не видел чужие сделки/клиентов.
          // Для нового пользователя defaultState() ставит view: "crm" — этого достаточно.
          const currentAgencyId = getAgencyId();
          const lastAgencyId = lsGet(LAST_AGENCY_KEY);
          if (!lastAgencyId || lastAgencyId !== currentAgencyId) {
            state = defaultState();
            lsRemove(STORAGE_KEY);
          }
          lsSet(LAST_AGENCY_KEY, currentAgencyId);
          await _loadCloudState();
          // Черновик из публичного калькулятора (?calc=…, кнопка «Сохранить в аккаунт»)
          // — после загрузки облака, иначе облачный снапшот стёр бы то, что человек
          // только что построил без регистрации. Одноразово: не переносить его же
          // при следующем логине с другого устройства.
          const importedFromCalc = _maybeImportCalcDraft();
          // Демо-сделка для брэнд-нового аккаунта — после сброса state и загрузки
          // (пустого) облака, иначе снапшот бы её стёр. Аха-момент вместо пустого экрана.
          // Если человек только что принёс смету из калькулятора — это и есть его
          // аха-момент, вторая демо-сделка поверх была бы лишней.
          if (_justRegistered) { _justRegistered = false; if (!importedFromCalc) _seedDemoDeal(); }
        } catch (e) {
          // Без этого catch — при брошенном исключении (сеть/CSP/таймаут) _dataLoading
          // оставался true навсегда: пользователь после УСПЕШНОГО входа зависал на
          // loading-заставке без единого сообщения, чинилось только перезагрузкой страницы.
          console.warn("User login data load:", e);
        }
        _dataLoading = false;
        _initRealtimeChannel();
        renderAdminTopbar();
        render();
        checkPaymentReturn();
        checkGoogleCalendarReturn();
        _loadGoogleCalendarStatus();
      }

      async function _loadUserProfile(userId, email) {
        if (!_supabase) return;
        try {
          const { data } = await _supabase.from("profiles").select("*").eq("id", userId).single();
          if (data) {
            _userProfile = data;
            // Migrate old profiles: set agency_id = own userId if missing
            if (!_userProfile.agency_id) {
              _userProfile.agency_id = userId;
              await _supabase.from("profiles").update({ agency_id: userId }).eq("id", userId);
            }
            // Sync avatar from cloud to local settings
            if (data.avatar_url) {
              const local = getUserSettings();
              if (!local.avatarDataUrl || local.avatarDataUrl !== data.avatar_url) {
                saveUserSettings({ avatarDataUrl: data.avatar_url });
              }
            }
          } else {
            // First-time user — create profile
            const trial_expires = new Date(Date.now() + 7 * 86400000).toISOString();
            const inviteCode = (_pendingInviteCode || "").trim();
            let agencyId = inviteCode || userId;
            let joinedTeam = inviteCode && inviteCode !== userId;

            // Check user limit for the agency being joined
            if (joinedTeam) {
              const { data: ownerProfile } = await _supabase.from("profiles").select("subscription_status,subscription_expires_at").eq("id", inviteCode).single();
              const { count: memberCount } = await _supabase.from("profiles").select("id", { count: "exact", head: true }).eq("agency_id", inviteCode);
              // Мест даёт факт оплаты, а не длина купленного периода — см. maxUsersForProfile.
              const maxUsers = maxUsersForProfile(ownerProfile);
              if ((memberCount || 0) >= maxUsers) {
                agencyId = userId; // reject invite, create own account
                joinedTeam = false;
                setTimeout(() => toast(`⚠️ Агентство достигло лимита пользователей (${maxUsers}) по тарифу. Создан личный аккаунт.`), 1200);
              }
            }

            const newProfile = {
              id: userId, email,
              agency_id: agencyId,
              subscription_status: "trial",
              subscription_plan: "pro",
              subscription_expires_at: trial_expires
            };
            await _supabase.from("profiles").upsert(newProfile);
            _userProfile = newProfile;
            _pendingInviteCode = "";
            if (!joinedTeam) { trackGoal("registration"); trackGoal("trial_started"); _justRegistered = true; }
            setTimeout(() => {
              if (joinedTeam) {
                pushNotification("info", "👥 Вы вошли в команду!", "Теперь вы работаете в общем рабочем пространстве агентства.", "");
                lsSet(STORAGE_KEY, JSON.stringify(state));
                toast("👥 Вы присоединились к агентству!");
              } else {
                pushNotification("info", "👋 Добро пожаловать в ADERVIS CRM!", "7 дней бесплатно и без карты. Начните с создания первой сделки!", "");
                lsSet(STORAGE_KEY, JSON.stringify(state));
                toast("🎉 Аккаунт создан! 7 дней бесплатного доступа.");
                // Приветственный email — fire-and-forget, не блокируем UI
                if (_adminSession) {
                  const { url: _sbUrl } = getSupabaseConfig();
                  fetch(`${_sbUrl}/functions/v1/welcome-email`, {
                    method: "POST",
                    headers: { "Content-Type": "application/json", "Authorization": `Bearer ${_adminSession.access_token}` },
                    body: "{}",
                  }).catch(() => {});
                }
                if (lsGet("adervis_tour_done") !== "1") {
                  setTimeout(startTour, 700);
                }
              }
            }, 1200);
          }
        } catch(e) { console.warn("Profile load:", e); }
      }

      // ── Web Push ────────────────────────────────────────────────────────────
      function _urlBase64ToUint8Array(base64String) {
        const padding = '='.repeat((4 - base64String.length % 4) % 4);
        const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
        const raw = atob(base64);
        return Uint8Array.from([...raw].map(c => c.charCodeAt(0)));
      }

      async function subscribeToPush() {
        if (!('serviceWorker' in navigator) || !('PushManager' in window)) {
          toast('Push-уведомления не поддерживаются в этом браузере'); return;
        }
        try {
          const perm = await Notification.requestPermission();
          if (perm !== 'granted') { toast('Разрешение на уведомления отклонено'); return; }
          const reg = await navigator.serviceWorker.ready;
          const sub = await reg.pushManager.subscribe({
            userVisibleOnly: true,
            applicationServerKey: _urlBase64ToUint8Array(VAPID_PUBLIC_KEY),
          });
          const { endpoint, keys } = sub.toJSON();
          if (!_supabase || !keys) return;
          await _supabase.from('push_subscriptions').upsert({
            agency_id: getAgencyId(),
            user_id:   _adminSession.user.id,
            endpoint,
            p256dh:    keys.p256dh,
            auth_key:  keys.auth,
          }, { onConflict: 'agency_id,endpoint' });
          toast('✅ Push-уведомления включены');
          render();
        } catch(e) { console.error('Push subscribe:', e); toast('Ошибка подписки на уведомления'); }
      }

      async function unsubscribeFromPush() {
        try {
          const reg = await navigator.serviceWorker.ready;
          const sub = await reg.pushManager.getSubscription();
          if (sub) {
            await _supabase.from('push_subscriptions').delete().eq('endpoint', sub.endpoint);
            await sub.unsubscribe();
          }
          toast('Push-уведомления отключены');
          render();
        } catch(e) { toast('Ошибка отписки'); }
      }

      async function getPushSubscriptionState() {
        if (!('serviceWorker' in navigator) || !('PushManager' in window)) return 'unsupported';
        try {
          const reg = await navigator.serviceWorker.ready;
          const sub = await reg.pushManager.getSubscription();
          return sub ? 'subscribed' : 'unsubscribed';
        } catch(e) { return 'unsubscribed'; }
      }

      async function sendWebPush(title, body, url) {
        if (!_supabase || !_adminSession) return;
        const { url: sbUrl } = getSupabaseConfig();
        try {
          await fetch(`${sbUrl}/functions/v1/web-push-send`, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': `Bearer ${_adminSession.access_token}`,
            },
            body: JSON.stringify({ agencyId: getAgencyId(), title, body, url }),
          });
        } catch(e) { /* push — нет критического значения, не прерываем */ }
      }

