      async function _applyReferralCode(userId) {
        const refCode = lsGet('_refCode');
        if (!refCode || !_supabase || !_userProfile) return;
        // Не применяем если уже записан или это собственный agency_id
        if (_userProfile.referred_by_agency_id) { lsRemove('_refCode'); return; }
        if (refCode === _userProfile.agency_id) { lsRemove('_refCode'); return; }
        await _supabase.from('profiles')
          .update({ referred_by_agency_id: refCode })
          .eq('id', userId)
          .is('referred_by_agency_id', null);
        lsRemove('_refCode');
      }

      function getAgencyId() {
        return (_userProfile && _userProfile.agency_id) || (_adminSession && _adminSession.user.id) || "local";
      }

      function _migrateStateData() {
        // Migrate old CRM statuses: "Закрыто" → "Завершённые", "Отказ" → "Архив"
        (state.savedProjects || []).forEach(p => {
          if (p.crmStatus === "Закрыто") p.crmStatus = "Завершённые";
          if (p.crmStatus === "Отказ") p.crmStatus = "Архив";
          if (p.crmStatusBeforeArchive === "Отказ") p.crmStatusBeforeArchive = "Архив";
        });
      }

      const SYNC_SKIP_KEYS = new Set(["view","mainMenuOpen","adminModal","clientModal","taskModal","taskModalSource","financeModal","editTransactionModal","wizard","dealModal","dealSwitcherOpen","packageEditModal","crmSelectMode","taskDetailsOpen","lineCommentsOpen","catalogEditId","helpModal","docsModal","docsTab","notifPopupOpen","summaryOpen","briefEditorType"]);

      // Кладёт облачное состояние в state. Отдельно от _loadCloudState, потому что
      // вызывается ещё и из разрешения конфликта.
      function _applyCloudState(cloudState) {
        const localSnap = JSON.stringify(Object.fromEntries(Object.entries(state).filter(([k]) => !SYNC_SKIP_KEYS.has(k))));
        Object.entries(cloudState).forEach(([k, v]) => {
          if (!SYNC_SKIP_KEYS.has(k)) state[k] = v;
        });
        const cloudSnap = JSON.stringify(Object.fromEntries(Object.entries(state).filter(([k]) => !SYNC_SKIP_KEYS.has(k))));
        // ВАЖНО: облачную копию надо прогнать через ту же миграцию схемы, что и
        // локальную в load(). Раньше здесь был только _migrateStateData() (он
        // переименовывает CRM-статусы), а migrateState()/normalizeState() — нет.
        // Из-за cache-first Service Worker два устройства спокойно крутят разные
        // версии кода: свежая версия, прочитав облако от старой, оставалась без
        // дефолтов новых полей и без normalizeSavedProject/normalizeTask — до
        // следующей перезагрузки страницы.
        state = migrateState(state);
        normalizeState();
        _migrateStateData();
        return localSnap !== cloudSnap;
      }

      async function _loadCloudState() {
        if (!_supabase || !_adminSession) return;
        const agencyId = getAgencyId();
        try {
          const { data } = await _supabase.from("agency_state").select("state_json,updated_at").eq("id", agencyId).single();
          if (!data || !data.state_json) return;

          // Есть ли на ЭТОМ устройстве правки, которые не доехали до облака?
          // _cloudDirty жил только в памяти и после перезагрузки обнулялся, поэтому
          // раньше облако раскладывалось поверх локального безусловно: правки,
          // сделанные в офлайне, молча заменялись более старым облаком, а
          // пользователь видел бодрое «Данные синхронизированы из облака».
          const mark = _getCloudSyncMark();
          const localAhead = !!(mark && mark.dirty && mark.agencyId === agencyId);
          const cloudMovedOn = !!(mark && mark.cloudUpdatedAt && data.updated_at
            && new Date(data.updated_at) > new Date(mark.cloudUpdatedAt));

          if (localAhead && !cloudMovedOn) {
            // Локальное строго новее: облако не двигалось с нашей последней удачной
            // записи. Ничего не тянем — досылаем своё.
            toast("☁️ Отправляем изменения, сделанные без сети");
            saveToCloud();
            return;
          }

          if (localAhead && cloudMovedOn) {
            // Настоящий конфликт: и здесь есть несинхронизированные правки, и в
            // облаке появилась более новая версия (другое устройство). Молча
            // затирать нельзя ни то, ни другое — спрашиваем.
            const takeCloud = await confirmDialog({
              title: "Данные расходятся",
              message: "На этом устройстве есть изменения, которые не успели уйти в облако, "
                + "а в облаке уже есть более новая версия с другого устройства.\n\n"
                + "«Взять из облака» — локальные изменения этого устройства будут потеряны.\n"
                + "«Оставить мои» — версия из облака будет заменена данными этого устройства.",
              okText: "Взять из облака",
              cancelText: "Оставить мои",
              danger: true
            });
            if (!takeCloud) {
              toast("☁️ Оставили данные этого устройства");
              saveToCloud();
              return;
            }
          }

          if (_applyCloudState(data.state_json)) toast("☁️ Данные синхронизированы из облака");
          // Локальное больше не «впереди» — оно теперь копия облачного.
          _setCloudSyncMark({ agencyId, cloudUpdatedAt: data.updated_at || null, dirty: false });
        } catch(e) { console.warn("Cloud load:", e); }
      }

      function _setCloudSaveIndicator(ok) {
        const ind = document.getElementById("autoSaveIndicator");
        if (!ind) return;
        if (!ok) {
          ind.textContent = "⚠ Не в облаке";
          ind.className = "autosave-indicator cloud-error show";
        } else {
          ind.textContent = "Сохранено";
          ind.className = "autosave-indicator show";
          setTimeout(() => { ind.classList.remove("show"); }, 2000);
        }
      }

      function saveToCloud() {
        if (!_supabase || !_adminSession) return;
        const agencyId = getAgencyId();
        clearTimeout(_cloudSaveTimer);
        _cloudSaveTimer = setTimeout(async () => {
          const data = Object.fromEntries(Object.entries(state).filter(([k]) => !SYNC_SKIP_KEYS.has(k)));
          const updatedAt = new Date().toISOString();
          try {
            // supabase-js v2 не бросает исключение — ошибка приходит в результате
            const { error } = await _supabase.from("agency_state").upsert({ id: agencyId, state_json: data, updated_at: updatedAt });
            if (error) throw error;
            // Запоминаем НАДОЛГО (не только в памяти), какую облачную версию мы
            // подтвердили: следующий запуск по этой метке поймёт, впереди ли локальное.
            _setCloudSyncMark({ agencyId, cloudUpdatedAt: updatedAt, dirty: false });
            if (_cloudDirty) {
              _cloudDirty = false;
              _setCloudSaveIndicator(true);
              toast("☁️ Синхронизировано с облаком");
            }
          } catch(e) {
            const firstFail = !_cloudDirty;
            _cloudDirty = true;
            _setCloudSaveIndicator(false);
            if (firstFail) toast("⚠️ Не удалось сохранить в облако — изменения пока хранятся локально");
            console.warn("Cloud save:", e);
          }
        }, 3000);
      }

      function _isSuperAdmin() {
        return !!(_adminSession && _adminSession.user.email === atob("YWRlcnZpcy5kaWdpdGFsQGdtYWlsLmNvbQ=="));
      }

      function isSubscriptionActive() {
        if (_isSuperAdmin()) return true;
        if (!_adminSession) return true; // local mode — no Supabase auth
        if (!_userProfile) return false; // session exists but profile failed to load
        const s = _userProfile.subscription_status;
        // Срок проверяется и у платной подписки: раньше "active" пропускал вообще
        // без проверки, из-за чего оплаченный месяц не заканчивался никогда.
        // Ночной крон expire-subscriptions-daily переведёт статус в "expired",
        // но доступ закрывается сразу, не дожидаясь его.
        if (s === "active" || s === "trial") {
          const exp = _userProfile.subscription_expires_at;
          return !exp || new Date(exp) > new Date();
        }
        return false;
      }

      // Именно ОПЛАЧЕННЫЙ тариф, без пробного периода. Нужно там, где право даётся
      // за деньги, а не за факт живого доступа: например снятие подписи
      // «Сделано в ADERVIS CRM» с клиентского портала (white-label).
      function isPaidPlan() {
        if (_isSuperAdmin()) return true;
        if (!_adminSession) return false;
        if (!_userProfile || _userProfile.subscription_status !== "active") return false;
        const exp = _userProfile.subscription_expires_at;
        return !exp || new Date(exp) > new Date();
      }

      function getSubscriptionLabel() {
        if (_isSuperAdmin()) return "Super Admin ∞";
        if (!_userProfile) return "";
        const s = _userProfile.subscription_status;
        const plan = _userProfile.subscription_plan || "pro";
        const exp = _userProfile.subscription_expires_at;
        if (s === "trial") {
          const days = exp ? Math.max(0, Math.round((new Date(exp) - new Date()) / 86400000)) : 0;
          return `Пробный · осталось ${days} д.`;
        }
        if (s === "active") return `${plan === "team" ? "Команда" : "Про"} ✓`;
        if (s === "expired") return "Подписка истекла";
        if (s === "cancelled") return "Подписка отменена";
        return s;
      }

      // Короткое название плана без счётчика дней — для использования в dropdown
      function getSubscriptionPlanName() {
        if (_isSuperAdmin()) return "Super Admin";
        if (!_userProfile) return "";
        const s = _userProfile.subscription_status;
        const plan = _userProfile.subscription_plan || "pro";
        if (s === "trial") return "Пробный период";
        if (s === "active") return plan === "team" ? "Команда" : "Про";
        if (s === "expired") return "Подписка истекла";
        if (s === "cancelled") return "Подписка отменена";
        return s;
      }

      // Количество дней до конца подписки/триала (null если неприменимо)
      function getSubscriptionDaysLeft() {
        if (!_userProfile) return null;
        const exp = _userProfile.subscription_expires_at;
        if (!exp) return null;
        return Math.max(0, Math.round((new Date(exp) - new Date()) / 86400000));
      }

      function _initRealtimeChannel() {
        if (!_supabase) return;
        if (_realtimeChannel) _realtimeChannel.unsubscribe();
        const myEmail = _adminSession && _adminSession.user && _adminSession.user.email || "";
        const _channelAgencyId = getAgencyId();
        _realtimeChannel = _supabase.channel(`adervis-crm-${_channelAgencyId}`, {
          config: { presence: { key: myEmail } }
        });
        _realtimeChannel
          .on("broadcast", { event: "state-sync" }, ({ payload }) => {
            if (!payload || !payload.data) return;
            if (payload.sender && payload.sender === myEmail) return;
            const active = document.activeElement;
            if (active && active.matches && active.matches("input, textarea, [data-autosave]")) {
              // Пользователь прямо сейчас печатает в это поле — полная замена state
              // снапшотом коллеги стёрла бы ещё не отправленный символ (broadcastState
              // из save() debounce'ится на 1200мс) без единого предупреждения. Откладываем
              // применение снапшота до потери фокуса этим полем.
              active.addEventListener("blur", () => _applyRemoteStateSync(payload), { once: true });
              return;
            }
            _applyRemoteStateSync(payload);
          })
          .on("presence", { event: "sync" }, () => {
            const presState = _realtimeChannel.presenceState();
            _onlineUsers = Object.keys(presState).filter(k => k !== myEmail && k !== "");
            renderAdminTopbar();
          })
          .on("postgres_changes", {
            event: "UPDATE",
            schema: "public",
            table: "profiles",
            filter: _adminSession ? `id=eq.${_adminSession.user.id}` : undefined
          }, (payload) => {
            if (payload.new) {
              _userProfile = Object.assign({}, _userProfile, payload.new);
              renderAdminTopbar();
              render();
            }
          })
          .subscribe(async (status) => {
            if (status === "SUBSCRIBED" && myEmail) {
              await _realtimeChannel.track({ email: myEmail });
            }
          });
      }

      function _applyRemoteStateSync(payload) {
        const incoming = payload.data;
        SYNC_SKIP_KEYS.forEach(k => { if (k in state) incoming[k] = state[k]; });
        Object.assign(state, incoming);
        // Как и с облачной копией: снапшот коллеги мог прийти от другой версии
        // приложения (cache-first SW держит устройства на разных версиях), поэтому
        // прогоняем через миграцию схемы, а не только через normalizeState.
        state = migrateState(state);
        _needsNormalize = true;
        render();
        toast("🔄 Обновление от " + (payload.sender || "коллеги"));
      }

      function broadcastState() {
        if (!_realtimeChannel || !_adminSession) return;
        clearTimeout(_broadcastTimer);
        _broadcastTimer = setTimeout(() => {
          const data = Object.fromEntries(Object.entries(state).filter(([k]) => !SYNC_SKIP_KEYS.has(k)));
          _realtimeChannel.send({ type: "broadcast", event: "state-sync",
            payload: { data, sender: _adminSession.user.email } });
        }, 1200);
      }

