      /* ─── USER AVATAR UPLOAD (resizes to 80px, syncs to Supabase) ─── */
      function uploadUserAvatar(event) {
        const file = event.target && event.target.files && event.target.files[0];
        if (!file || !file.type.startsWith("image/")) return;
        const reader = new FileReader();
        reader.onload = () => {
          // Resize to 80×80 via canvas before storing
          const img = new Image();
          img.onload = () => {
            const SIZE = 80;
            const canvas = document.createElement("canvas");
            canvas.width = SIZE; canvas.height = SIZE;
            const ctx = canvas.getContext("2d");
            const side = Math.min(img.width, img.height);
            const ox = (img.width - side) / 2, oy = (img.height - side) / 2;
            ctx.drawImage(img, ox, oy, side, side, 0, 0, SIZE, SIZE);
            const dataUrl = canvas.toDataURL("image/jpeg", 0.8);
            saveUserSettings({ avatarDataUrl: dataUrl });
            _syncAvatarToCloud(dataUrl);
            render();
            toast("Фото профиля обновлено");
          };
          img.src = String(reader.result || "");
        };
        reader.readAsDataURL(file);
      }
      function removeUserAvatar() {
        saveUserSettings({ avatarDataUrl: "" });
        _syncAvatarToCloud("");
        render();
        toast("Фото удалено");
      }
      async function _syncAvatarToCloud(dataUrl) {
        if (!_supabase || !_adminSession) return;
        try {
          await _supabase.from("profiles").update({ avatar_url: dataUrl || null }).eq("id", _adminSession.user.id);
        } catch(e) { console.warn("Avatar sync:", e); }
      }

      /* ─── GLOBAL SEARCH ─── */
      function openSearch() {
        const m = document.getElementById("searchModal");
        if (m) { m.style.display = "flex"; setTimeout(() => { const i = document.getElementById("searchInput"); if(i){i.value="";i.focus();} runSearch(""); }, 10); }
      }
      function closeSearch() {
        const m = document.getElementById("searchModal");
        if (m) m.style.display = "none";
      }
      function runSearch(q) {
        clearTimeout(runSearch._t);
        runSearch._t = setTimeout(() => _execSearch(q), 150);
      }

      function _execSearch(q) {
        const el = document.getElementById("searchResults");
        if (!el) return;
        q = (q || "").toLowerCase().trim();
        if (!q) {
          el.innerHTML = `
            <div style="padding:20px 16px 8px">
              <div style="display:flex;flex-wrap:wrap;gap:6px">
                ${["Сделки","Клиенты","Задачи","База знаний"].map(h=>`<span style="font-size:12px;background:var(--panel2);border:1px solid var(--line);border-radius:99px;padding:3px 10px;color:var(--muted)">${h}</span>`).join("")}
              </div>
              <div style="font-size:12px;color:var(--hint);margin-top:12px;padding:0 2px">Поиск по всем сделкам, клиентам, задачам и базе знаний</div>
            </div>`;
          return;
        }
        const safe = q.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
        const hl = t => highlightText(t, q);
        const results = [];
        (state.savedProjects || []).forEach(p => {
          if ((p.name||"").toLowerCase().includes(q) || (p.client||"").toLowerCase().includes(q)) {
            results.push({ type: "deal", icon: "📋", color: "rgba(124,58,237,.15)", name: p.name || "Без названия", sub: `${p.client||""} · ${money(p.total||0)} · ${p.crmStatus||"Лид"}`, action: `app.openDeal('${p.id}');app.closeSearch()` });
          }
        });
        (state.clients || []).forEach(c => {
          if ((c.name||"").toLowerCase().includes(q) || (c.company||"").toLowerCase().includes(q) || (c.phone||"").includes(q)) {
            results.push({ type: "client", icon: "👤", color: "rgba(37,99,235,.15)", name: c.name || "Клиент", sub: `${c.company||""} · ${c.phone||""}`, action: `app.go('clients');app.closeSearch()` });
          }
        });
        // Задачи по ВСЕМ сделкам (не только активной) — та же агрегация, что и на
        // странице «Задачи», иначе поиск находил только задачи текущего открытого проекта.
        _collectAllTasks().forEach(row => {
          const t = row.task;
          if ((t.title||"").toLowerCase().includes(q)) {
            const action = row.kind === "global"
              ? `app.go('global-tasks');app.setGlobalTaskFilter('project','personal');app.closeSearch()`
              : `app.loadSavedProject('${row.projectId}');app.setDealView('tasks');app.closeSearch()`;
            results.push({ type: "task", icon: "✅", color: "rgba(8,145,178,.15)", name: t.title, sub: `${t.status||""}${row.projectName ? " · " + row.projectName : ""}`, action });
          }
        });
        (state.knowledgeDocs || []).forEach(d => {
          if ((d.title||"").toLowerCase().includes(q) || (d.content||"").toLowerCase().includes(q)) {
            results.push({ type: "kb", icon: "📄", color: "rgba(22,163,74,.15)", name: d.title || "Документ", sub: KB_CATS[d.cat] || "Без категории", action: `app.go('knowledge');app.kbOpen('${d.id}');app.closeSearch()` });
          }
        });
        if (!results.length) {
          el.innerHTML = `
            <div style="padding:32px 20px;text-align:center">
              <div style="font-size:28px;margin-bottom:10px;opacity:.4">🔍</div>
              <div style="color:var(--text);font-size:13px;font-weight:600;margin-bottom:4px">Ничего не найдено</div>
              <div style="color:var(--muted);font-size:12px">Нет результатов по «${escapeHtml(q)}»</div>
            </div>`;
          return;
        }
        // Сортировка: точное совпадение выше, потом по длине
        results.sort((a, b) => {
          const aExact = a.name.toLowerCase() === q;
          const bExact = b.name.toLowerCase() === q;
          if (aExact && !bExact) return -1;
          if (!aExact && bExact) return 1;
          const aStarts = a.name.toLowerCase().startsWith(q);
          const bStarts = b.name.toLowerCase().startsWith(q);
          if (aStarts && !bStarts) return -1;
          if (!aStarts && bStarts) return 1;
          return a.name.length - b.name.length;
        });
        // Группируем по типам
        const groups = [
          { key: "deal",   label: "Сделки"  },
          { key: "client", label: "Клиенты" },
          { key: "task",   label: "Задачи"  },
          { key: "kb",     label: "База знаний" },
        ];
        el.innerHTML = groups.map(g => {
          const all = results.filter(r => r.type === g.key);
          const items = all.slice(0, 5);
          if (!items.length) return "";
          const more = all.length - 5;
          return `<div class="search-section">${g.label}${all.length > 5 ? ` <span style="font-weight:400;opacity:.6">(${all.length})</span>` : ""}</div>` +
            items.map(r => `
              <div class="search-result" onclick="${r.action}">
                <div class="search-result-icon" style="background:${r.color}">${r.icon}</div>
                <div><div class="search-result-name">${hl(r.name)}</div><div class="search-result-sub">${hl(r.sub)}</div></div>
              </div>`).join("") +
            (more > 0 ? `<div style="padding:6px 16px 8px;font-size:12px;color:var(--muted)">и ещё ${more} результатов</div>` : "");
        }).join("");
      }

      /* ─── DUPLICATE DEAL ─── */
      function duplicateDeal(projectId) {
        if (checkTrialDealLimit()) return;
        const proj = state.savedProjects.find(p => p.id === projectId);
        if (!proj) return;
        const copy = deepClone(proj);
        copy.id = uid("proj");
        copy.name = (proj.name || "Проект") + " (копия)";
        copy.crmStatus = "Лид";
        copy.createdAt = new Date().toISOString();
        copy.updatedAt = copy.createdAt;
        copy.paid = 0; copy.debt = copy.total || 0; copy.expensesTotal = 0; copy.profit = copy.total || 0;
        copy.portalId = "";
        copy.activity = [];
        // Копия не должна ссылаться на Google-событие оригинала — та же грабля,
        // что чинили в duplicateSavedProject()/repeatSavedProject().
        copy.googleEventIds = {};
        if (copy.snapshot) {
          if (copy.snapshot.project) { copy.snapshot.project.name = copy.name; copy.snapshot.project.crmStatus = "Лид"; copy.snapshot.project.portalId = ""; }
          // Reset execution data — keep only estimate structure
          copy.snapshot.payments = []; copy.snapshot.expenses = []; copy.snapshot.team = [];
          // Give new IDs to tasks so they don't collide
          if (copy.snapshot.tasks) copy.snapshot.tasks = copy.snapshot.tasks.map(t => ({ ...t, id: uid("task") }));
        }
        state.savedProjects.unshift(copy);
        save(); render();
        toast("✅ Сделка продублирована: " + copy.name);
      }

      function _saveUserField(key, value) {
        saveUserSettings({ [key]: value });
        // Update avatar in topbar without full re-render
        if (key === "displayName") {
          const paBtn = document.getElementById("profileAvatarBtn");
          const paInner = document.getElementById("profileAvatarInner");
          if (paInner && !getUserSettings().avatarDataUrl) {
            const email = _adminSession ? _adminSession.user.email : "";
            const n = (value || email || "A")[0].toUpperCase();
            paInner.textContent = n;
          }
        }
      }

      function renderAuthGateEl() {
        const el = document.getElementById("authGateContainer");
        if (!el) return;
        if (_briefAgencyId || _portalId || _calcMode) { el.innerHTML = ""; return; }
        const cfg = getSupabaseConfig();
        const localMode = lsGet("adervis_local_mode") === "1";
        // Пока проверяем сохранённую сессию — auth gate не показываем (бесшовная загрузка)
        if (_authChecking || !cfg.url || !cfg.key || localMode || _adminSession) {
          el.innerHTML = "";
        } else {
          el.innerHTML = renderAuthGate();
          _vkidInited = false;
          setTimeout(() => _ensureVKIDSDK().then(initVKIDWidget).catch(e => console.warn("VK ID SDK:", e)), 50);
        }
      }

      function _promoCodeInputHtml() {
        const promoValid   = _promoState && typeof _promoState === "object";
        const promoInvalid = _promoState === "invalid";
        const promoChecking = _promoState === "checking";
        const borderColor = promoValid ? "var(--green)" : promoInvalid ? "var(--red)" : "var(--line)";
        const statusHtml = promoValid
          ? `<span style="color:var(--green);font-size:12px;font-weight:600">✓ −${_promoState.discount}% применено</span>`
          : promoInvalid
            ? `<span style="color:var(--red);font-size:12px">Промокод не найден или истёк</span>`
            : promoChecking
              ? `<span style="color:var(--muted);font-size:12px">Проверяем...</span>`
              : "";
        return `
          <div style="display:flex;align-items:center;gap:8px;margin-bottom:16px;flex-wrap:wrap">
            <div style="display:flex;align-items:center;gap:0;border:1px solid ${borderColor};border-radius:8px;overflow:hidden;background:var(--input);transition:.15s">
              <input
                type="text"
                placeholder="Промокод"
                value="${escapeHtml(_promoCode)}"
                maxlength="32"
                style="border:none;background:transparent;padding:9px 12px;font-size:13px;color:var(--text);width:160px;outline:none"
                oninput="app._promoInput(this.value)"
                onkeydown="if(event.key==='Enter')app.validatePromo()"
              >
              ${promoValid
                ? `<button onclick="app.clearPromo()" style="border:none;background:transparent;color:var(--muted);padding:9px 10px;cursor:pointer;font-size:16px" title="Убрать промокод">✕</button>`
                : `<button onclick="app.validatePromo()" style="border:none;background:var(--primary);color:#fff;padding:9px 14px;cursor:pointer;font-size:13px;font-weight:600" ${promoChecking ? "disabled" : ""}>${promoChecking ? "..." : "→"}</button>`
              }
            </div>
            ${statusHtml}
          </div>`;
      }

      function renderSubscriptionGate() {
        const email = _adminSession && _adminSession.user.email || "";
        const hasSupabase = !!getSupabaseConfig().url;
        const paidPlans = PLANS.filter(p => p.price > 0);
        const promoValid = _promoState && typeof _promoState === "object";
        const promoInvalid = _promoState === "invalid";
        const promoChecking = _promoState === "checking";
        return `
          <div style="display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:70vh;text-align:center;padding:32px 16px">
            <div style="font-size:48px;margin-bottom:18px">🔒</div>
            <h1 style="font-size:26px;margin-bottom:10px">Подписка истекла</h1>
            <p style="max-width:420px;margin-bottom:8px;line-height:1.55;color:var(--muted)">
              Аккаунт <strong style="color:var(--text)">${escapeHtml(email)}</strong>. Выберите тариф, чтобы продолжить работу.
            </p>
            <p style="max-width:420px;margin-bottom:28px;font-size:12px;color:var(--green)">
              ✅ Все сделки, клиенты и сметы сохранены — после оплаты вы продолжите с того же места
            </p>
            ${hasSupabase ? `
              <div style="display:flex;flex-wrap:wrap;gap:12px;justify-content:center;max-width:640px;margin-bottom:24px">
                ${paidPlans.map(p => {
                  const isLoading = _buyingPlan === p.id;
                  const discountedPrice = promoValid ? Math.round(p.price * (1 - _promoState.discount / 100)) : null;
                  return `
                    <div style="background:var(--panel2);border:1px solid ${p.popular ? "var(--primary)" : "var(--line)"};border-radius:16px;padding:18px 22px;min-width:140px;flex:1;max-width:180px;position:relative">
                      ${p.popular ? `<div style="position:absolute;top:-10px;left:50%;transform:translateX(-50%);background:var(--primary);color:#fff;font-size:12px;font-weight:700;border-radius:99px;padding:2px 10px">Популярный</div>` : ""}
                      <div style="font-size:13px;font-weight:700;margin-bottom:6px">${p.label}</div>
                      ${discountedPrice !== null
                        ? `<div style="font-size:14px;color:var(--muted);text-decoration:line-through;line-height:1">${p.price}₽</div><div style="font-size:22px;font-weight:900;color:var(--green);margin-bottom:2px">${discountedPrice}₽</div>`
                        : `<div style="font-size:22px;font-weight:900;margin-bottom:2px">${p.price}₽</div>`}
                      <div style="font-size:12px;color:var(--muted);margin-bottom:10px">${p.period}</div>
                      ${p.save ? `<div style="font-size:12px;color:var(--green);margin-bottom:8px">${p.save}</div>` : ""}
                      <button class="btn primary" style="width:100%;padding:9px;font-size:13px" onclick="app.buyPlan('${p.id}')" ${isLoading ? "disabled" : ""}>
                        ${isLoading ? "⏳..." : "Оплатить →"}
                      </button>
                    </div>`;
                }).join("")}
              </div>
              ${_promoCodeInputHtml()}
              <p style="font-size:12px;color:var(--muted);margin-bottom:20px">Безопасная оплата через ЮKassa · карта / СБП / ЮМани</p>
            ` : `
              <a href="mailto:adervis.digital@gmail.com?subject=Продление подписки ADERVIS CRM" class="btn primary" style="text-decoration:none;margin-bottom:20px">
                📧 Продлить по email
              </a>
            `}
            <button class="btn small" onclick="app.adminLogout()">Выйти</button>
          </div>
        `;
      }

      function renderPayBanner() {
        if (!_adminSession || !_userProfile) return "";
        // Проверяем — пользователь скрыл баннер в этой сессии
        if (sessionStorage.getItem("pay_banner_dismissed") === "1") return "";

        const sub = _userProfile;
        const s = sub.subscription_status;
        const exp = sub.subscription_expires_at ? new Date(sub.subscription_expires_at) : null;
        const daysLeft = exp ? Math.round((exp - new Date()) / 86400000) : null;

        const closeBtn = `<button onclick="event.stopPropagation();app.dismissPayBanner()" title="Скрыть" style="margin-left:4px;background:rgba(255,255,255,.2);border:none;border-radius:50%;width:22px;height:22px;display:grid;place-items:center;cursor:pointer;flex-shrink:0;color:#fff;font-size:14px;line-height:1">×</button>`;

        if (s === "trial" && daysLeft !== null) {
          if (daysLeft > 7) return "";
          const bg = daysLeft <= 2 ? "var(--red)" : daysLeft <= 4 ? "var(--orange)" : "var(--primary)";
          const msg = daysLeft <= 0
            ? "Пробный период истёк — оформите подписку"
            : daysLeft === 1
            ? "Пробный период заканчивается завтра"
            : `Пробный период: осталось ${daysLeft} дн.`;
          return `
            <div id="payBannerBar" style="position:fixed;bottom:70px;right:16px;z-index:200;background:${bg};color:#fff;border-radius:14px;padding:10px 16px;box-shadow:0 8px 28px rgba(0,0,0,.35);display:flex;align-items:center;gap:10px;font-size:13px;font-weight:600;max-width:340px">
              <span style="cursor:pointer;flex:1" onclick="app.gotoSubscription()">⏰ ${msg} — Выбрать тариф →</span>
              ${closeBtn}
            </div>`;
        }
        if (s === "active" && daysLeft !== null) {
          if (daysLeft > 7) return "";
          return `
            <div id="payBannerBar" style="position:fixed;bottom:70px;right:16px;z-index:200;background:var(--primary);color:#fff;border-radius:14px;padding:10px 16px;box-shadow:0 8px 28px rgba(124,58,237,.45);display:flex;align-items:center;gap:10px;font-size:13px;font-weight:600;max-width:340px">
              <span style="cursor:pointer;flex:1" onclick="app.gotoSubscription()">⚡ ${daysLeft <= 0 ? "Подписка истекает сегодня" : `Подписка: осталось ${daysLeft} дн.`} — Продлить →</span>
              ${closeBtn}
            </div>`;
        }
        return "";
      }

      function dismissPayBanner() {
        sessionStorage.setItem("pay_banner_dismissed", "1");
        const el = document.getElementById("payBannerContainer");
        if (el) el.innerHTML = "";
      }

      /* ═══════════════════════════════════════════════════════
         УВЕДОМЛЕНИЯ
      ═══════════════════════════════════════════════════════ */
      function pushNotification(type, title, body, projectId) {
        const n = { id: uid("notif"), type, title, body: body || "", projectId: projectId || "", read: false, createdAt: new Date().toISOString() };
        state.notifications = [n, ...(state.notifications || [])].slice(0, 100);
        renderNotifBadge();
      }

      function renderNotifBadge() {
        const badge = document.getElementById("notifBadge");
        if (!badge) return;
        const unread = (state.notifications || []).filter(n => !n.read).length;
        badge.textContent = unread > 9 ? "9+" : String(unread);
        badge.style.display = unread > 0 ? "flex" : "none";
      }

      function toggleNotifPopup() {
        const next = !state.notifPopupOpen;
        _closeOtherTopbarDropdowns("notif");
        state.notifPopupOpen = next;
        if (state.notifPopupOpen) {
          // Mark all as read
          (state.notifications || []).forEach(n => n.read = true);
          renderNotifBadge();
          save();
        }
        const el = document.getElementById("notifPopupContainer");
        if (!el) return;
        el.innerHTML = state.notifPopupOpen ? renderNotifPopup() : "";
        if (state.notifPopupOpen) {
          // close on outside click
          setTimeout(() => document.addEventListener("click", _closeNotifOnOutside, { once: true }), 10);
        }
      }

      function _closeNotifOnOutside(e) {
        if (!e.target.closest("#notifPopupContainer") && !e.target.closest("#notifBtn")) {
          state.notifPopupOpen = false;
          const el = document.getElementById("notifPopupContainer");
          if (el) el.innerHTML = "";
        }
      }

      function renderNotifPopup() {
        const notifs = state.notifications || [];
        const timeAgo = iso => {
          const ts = new Date(iso);
          if (!iso || isNaN(ts)) return "";
          const d = Math.floor((Date.now() - ts) / 1000);
          if (d < 60) return "только что";
          if (d < 3600) return Math.floor(d/60) + " мин назад";
          if (d < 86400) return Math.floor(d/3600) + " ч назад";
          return Math.floor(d/86400) + " дн назад";
        };
        return `
          <div class="notif-popup" id="notifPopup">
            <div class="notif-popup-header">
              <strong>Уведомления</strong>
              <div style="display:flex;gap:8px;align-items:center">
                ${notifs.length ? `<button style="background:none;border:none;font-size:12px;color:var(--muted);cursor:pointer" onclick="app.clearNotifs()">Очистить</button>` : ""}
                <button onclick="app.toggleNotifPopup()" style="background:none;border:none;font-size:20px;color:var(--muted);cursor:pointer;line-height:1;padding:0 2px">×</button>
              </div>
            </div>
            <div class="notif-list">
              ${notifs.length === 0 ? `
                <div style="padding:32px 20px;text-align:center">
                  <div style="font-size:28px;margin-bottom:10px;opacity:.5">🔔</div>
                  <div style="color:var(--text);font-size:13px;font-weight:600;margin-bottom:4px">Всё тихо</div>
                  <div style="color:var(--muted);font-size:12px">Уведомления о дедлайнах<br>и событиях появятся здесь</div>
                </div>` :
                notifs.map(n => `
                  <div class="notif-item ${n.read ? "" : "unread"}" onclick="app.notifClick('${n.id}')">
                    <div class="notif-dot"></div>
                    <div class="notif-body">
                      <strong>${escapeHtml(n.title)}</strong>
                      ${n.body ? escapeHtml(n.body) : ""}
                      <div class="notif-time">${timeAgo(n.createdAt)}</div>
                    </div>
                  </div>`).join("")
              }
            </div>
          </div>
        `;
      }

      function clearNotifs() {
        state.notifications = [];
        state.notifPopupOpen = false;
        const el = document.getElementById("notifPopupContainer");
        if (el) el.innerHTML = "";
        renderNotifBadge();
        save();
      }

      function notifClick(id) {
        const n = (state.notifications || []).find(x => x.id === id);
        if (n && n.projectId) { app.loadSavedProject(n.projectId); }
        toggleNotifPopup();
      }

      /* ═══════════════════════════════════════════════════════
         ПРОФИЛЬ И ТАРИФЫ
      ═══════════════════════════════════════════════════════ */
      // Планы = только периоды оплаты. Числа мест здесь СПЕЦИАЛЬНО больше нет:
      // раньше maxUsers рос вместе с months (1/1/3/5/10), из-за чего команда из трёх
      // человек была обязана купить сразу 3 месяца. Месяцы подписки и люди в команде —
      // разные оси; связка блокировала покупку и ничего не давала взамен (27.07.2026).
      // Теперь любой оплаченный период даёт одинаковые PAID_MAX_USERS мест.
      const PLANS = [
        { id: "trial",  label: "Пробный",    price: 0,   period: "7 дней бесплатно", save: "",             months: 0  },
        { id: "month1", label: "Месяц",       price: 490, period: "в месяц",            save: "",             months: 1  },
        { id: "month3", label: "3 месяца",    price: 390, period: "в месяц",            save: "Экономия 20%", months: 3, popular: true },
        { id: "month6", label: "6 месяцев",   price: 340, period: "в месяц",            save: "Экономия 31%", months: 6  },
        { id: "year",   label: "Год",         price: 290, period: "в месяц",            save: "Экономия 41%", months: 12 }
      ];

      // Мест в команде на любом оплаченном тарифе. Пробный период — как и раньше, один
      // пользователь: он про «посмотреть продукт», а не про работу командой.
      const PAID_MAX_USERS = 3;

      // Сколько мест даёт профиль. Считается по факту оплаты, а НЕ по длине периода.
      function maxUsersForProfile(profile) {
        if (!profile || profile.subscription_status !== "active") return 1;
        const exp = profile.subscription_expires_at;
        if (exp && new Date(exp) <= new Date()) return 1; // оплата закончилась
        return PAID_MAX_USERS;
      }

      // Лимит AI-генераций КП на пробном тарифе. Дублируется в Edge Function
      // ai-proposal — там он и решает: клиентская проверка лишь бережёт лишний запрос.
      const AI_PROPOSAL_TRIAL_LIMIT = 5;

      // ─── ADMIN PANEL ─────────────────────────────────────────────────────────
      let _adminPanelTab = "stats";
      let _settingsTab = "company";
      let _adminAgencies = null; // null = not loaded
      let _adminPromoCodes = null;
      let _adminStats = null;
      let _adminLoading = false;
      let _adminPromoForm = { code: "", discount: 0, expires: "", maxUses: 100, loading: false, error: "" };
      let _adminEditSub = null; // { agencyId, status, plan, expires }
      let _adminErrors = null; // сырые строки client_errors
      let _adminErrorsFilter = { q: "", kind: "" };
      let _adminErrorExpanded = null; // ключ развёрнутой группы

      async function loadAdminPanel() {
        if (!_isSuperAdmin() || !_supabase) return;
        _adminLoading = true; render();
        try {
          const [agRes, promoRes, errRes] = await Promise.all([
            _supabase.rpc("admin_get_all_users"),
            _supabase.rpc("admin_get_promo_codes"),
            _supabase.from("client_errors").select("*").order("created_at", { ascending: false }).limit(300)
          ]);
          if (agRes.error) throw new Error("admin_get_all_users: " + agRes.error.message);
          if (promoRes.error) throw new Error("admin_get_promo_codes: " + promoRes.error.message);
          if (errRes.error) throw new Error("client_errors: " + errRes.error.message);
          // admin_get_all_users возвращает json → data уже является массивом
          _adminAgencies = Array.isArray(agRes.data) ? agRes.data : (agRes.data || []);
          _adminPromoCodes = Array.isArray(promoRes.data) ? promoRes.data : (promoRes.data || []);
          _adminErrors = errRes.data || [];
          const now = new Date();
          const month1 = new Date(now.getFullYear(), now.getMonth(), 1);
          _adminStats = {
            total: _adminAgencies.length,
            active: _adminAgencies.filter(a => a.subscription_status === "active").length,
            trial: _adminAgencies.filter(a => a.subscription_status === "trial").length,
            newThisMonth: _adminAgencies.filter(a => a.created_at && new Date(a.created_at) >= month1).length,
            mrr: _adminAgencies.filter(a => a.subscription_status === "active").reduce((s, a) => {
              const plan = PLANS.find(p => p.id === a.subscription_plan);
              return s + (plan ? plan.price : PLANS.find(p => p.id === "month1").price);
            }, 0)
          };
        } catch(e) {
          console.warn("Admin load error:", e);
          toast("Ошибка: " + e.message);
          _adminAgencies = []; // предотвратить render-loop
          _adminPromoCodes = [];
          _adminErrors = [];
        }
        _adminLoading = false; render();
      }

      async function adminSetSubscription() {
        if (!_adminEditSub || !_supabase) return;
        const { agencyId, status, plan, expires } = _adminEditSub;
        const { error } = await _supabase.rpc("admin_set_subscription", {
          p_agency_id: agencyId,
          p_status: status,
          p_plan: plan,
          p_expires_at: expires || null
        });
        if (error) { toast("Ошибка: " + error.message); return; }
        toast("Подписка обновлена");
        _adminEditSub = null;
        loadAdminPanel();
      }

      async function adminCreatePromo() {
        const f = _adminPromoForm;
        if (!f.code.trim()) { toast("Введите код"); return; }
        if (!f.discount || f.discount <= 0) { toast("Введите скидку %"); return; }
        f.loading = true; render();
        try {
          const { error } = await _supabase.rpc("admin_create_promo", {
            p_code: f.code.trim(),
            p_discount: Number(f.discount),
            p_max_uses: Number(f.maxUses) || 100,
            p_expires: f.expires || null
          });
          f.loading = false;
          if (error) { f.error = error.message; render(); return; }
          toast("Промокод создан: " + f.code.toUpperCase());
          _adminPromoForm = { code: "", discount: 0, expires: "", maxUses: 100, loading: false, error: "" };
          loadAdminPanel();
        } catch (e) {
          f.loading = false;
          f.error = "Ошибка сети. Попробуйте ещё раз.";
          render();
        }
      }

      async function adminTogglePromo(id, active) {
        const { error } = await _supabase.rpc("admin_toggle_promo", { p_id: id, p_active: active });
        if (error) { toast("Ошибка: " + error.message); return; }
        loadAdminPanel();
      }

      async function _setExpenseBudget() {
        const cur = state.project.expenseBudget || 0;
        const val = await promptDialog({ title: "Плановый бюджет расходов", defaultValue: cur || "", placeholder: "Напр. 50000", okText: "Сохранить" });
        if (val === null) return;
        const n = numberValue(val, 0);
        state.project.expenseBudget = n;
        save(); render();
        toast(n > 0 ? `Бюджет расходов: ${money(n)}` : "Бюджет расходов удалён");
      }

      async function adminActivate(agencyId) {
        const expires = new Date(); expires.setDate(expires.getDate() + 30);
        const { error } = await _supabase.rpc("admin_set_subscription", {
          p_agency_id: agencyId, p_status: "active", p_plan: "month1", p_expires_at: expires.toISOString()
        });
        if (error) { toast("Ошибка: " + error.message); return; }
        toast("✅ Подписка активирована на 30 дней");
        loadAdminPanel();
      }

      async function adminExtendTrial(agencyId) {
        const agency = (_adminAgencies || []).find(a => a.agency_id === agencyId);
        const currentExpires = agency?.subscription_expires_at ? new Date(agency.subscription_expires_at) : new Date();
        const base = currentExpires > new Date() ? currentExpires : new Date();
        base.setDate(base.getDate() + 14);
        const { error } = await _supabase.rpc("admin_set_subscription", {
          p_agency_id: agencyId,
          p_status: "trial",
          p_plan: agency?.subscription_plan || "pro",
          p_expires_at: base.toISOString()
        });
        if (error) { toast("Ошибка: " + error.message); return; }
        toast("Триал продлён до " + base.toLocaleDateString("ru-RU"));
        loadAdminPanel();
      }

      async function adminToggleBlock(agencyId, currentStatus) {
        const newStatus = currentStatus === "blocked" ? "expired" : "blocked";
        const label = newStatus === "blocked" ? "Заблокировать" : "Разблокировать";
        if (!(await confirmDialog({ title: label + " пользователя?", message: "Изменить статус подписки этого агентства?", okText: label, danger: newStatus === "blocked" }))) return;
        const { error } = await _supabase.rpc("admin_set_subscription", {
          p_agency_id: agencyId,
          p_status: newStatus,
          p_plan: "pro",
          p_expires_at: null
        });
        if (error) { toast("Ошибка: " + error.message); return; }
        toast(newStatus === "blocked" ? "Пользователь заблокирован" : "Пользователь разблокирован");
        loadAdminPanel();
      }

      function _adminSubLabel(status) {
        return { trial: "Триал", active: "Активна", expired: "Истекла", blocked: "Заблок.", "": "Нет профиля" }[status || ""] || status;
      }
      function _adminPlanLabel(plan) {
        return { month1: "1 мес", month3: "3 мес", month6: "6 мес", year: "Год", pro: "PRO", "": "—" }[plan || ""] || plan;
      }
      function _adminDaysLeft(expiresAt) {
        if (!expiresAt) return null;
        const d = Math.round((new Date(expiresAt) - new Date()) / 86400000);
        if (d > 0) return `через ${d} дн.`;
        if (d === 0) return "сегодня";
        return `${Math.abs(d)} дн. назад`;
      }

      function renderAdminPanel() {
        if (!_isSuperAdmin()) return `<div class="panel"><p class="u-muted">Доступ запрещён.</p></div>`;
        if (_adminLoading) return `<div class="panel" style="text-align:center;padding:48px"><div class="spinner" style="margin:0 auto 12px"></div><p class="u-muted">Загрузка...</p></div>`;
        if (!_adminAgencies) { loadAdminPanel(); return `<div class="panel"><p class="u-muted">Загрузка...</p></div>`; }
        const s = _adminStats || {};

        const statusColor = { trial: "rgba(202,138,4,.15)", active: "rgba(22,163,74,.15)", expired: "rgba(220,38,38,.12)", blocked: "rgba(220,38,38,.2)", "": "var(--panel2)" };
        const statusText = { trial: "#f59e0b", active: "#4ade80", expired: "var(--red)", blocked: "var(--red)" };

        return `
          <div class="panel">
            <!-- Header -->
            <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:24px;flex-wrap:wrap;gap:12px">
              <div style="display:flex;align-items:center;gap:14px">
                <div style="width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,#dc2626,#7c3aed);display:grid;place-items:center;color:#fff">${icon("lock", 20)}</div>
                <div>
                  <h1 class="u-title-20">Admin Panel</h1>
                  <p style="margin:0;font-size:12px;color:var(--muted)">adervis.digital@gmail.com</p>
                </div>
              </div>
              <button class="btn small" onclick="app.loadAdminPanel()" style="display:flex;align-items:center;gap:6px">
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><path d="M3 12a9 9 0 101.77-5.5"/><path d="M3 3v4h4"/></svg>
                Обновить
              </button>
            </div>

            <!-- KPI strip -->
            <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:10px;margin-bottom:24px">
              ${[
                ["Всего", s.total||0, ""],
                ["Активных", s.active||0, "#4ade80"],
                ["На триале", s.trial||0, "#f59e0b"],
                ["Новых / мес", s.newThisMonth||0, "#60a5fa"],
                ["MRR", (s.mrr||0).toLocaleString("ru-RU")+" ₽", "#a78bfa"],
                ["ARR", ((s.mrr||0)*12).toLocaleString("ru-RU")+" ₽", "#a78bfa"]
              ].map(([label, val, color]) => `
                <div style="background:var(--panel2);border:1px solid var(--line);border-radius:12px;padding:14px 16px">
                  <div style="font-size:22px;font-weight:900;color:${color||"var(--text)"};font-variant-numeric:tabular-nums">${val}</div>
                  <div style="font-size:12px;color:var(--muted);margin-top:3px;font-weight:600">${label}</div>
                </div>`).join("")}
            </div>

            <!-- Tabs -->
            <div style="display:flex;gap:4px;margin-bottom:20px;background:var(--panel2);padding:4px;border-radius:12px;width:fit-content">
              ${[["users",icon("users"),"Пользователи"],["promos",icon("gift"),"Промокоды"],["errors",icon("bug"),"Ошибки" + ((_adminErrors||[]).length ? ` (${_adminErrors.length})` : "")]].map(([k,ic,l]) => `
                <button onclick="app._setAdminTab('${k}')"
                  style="display:inline-flex;align-items:center;gap:7px;padding:8px 18px;border-radius:9px;border:none;cursor:pointer;font-size:13px;font-weight:700;transition:.15s;
                  background:${_adminPanelTab===k?"var(--primary)":"transparent"};
                  color:${_adminPanelTab===k?"#fff":"var(--muted)"}">
                  ${ic}${l}
                </button>`).join("")}
            </div>

            <!-- Users tab -->
            ${_adminPanelTab === "users" ? `
              <div style="display:flex;flex-direction:column;gap:8px">
                ${(_adminAgencies||[]).map(a => {
                  const aid = escapeHtml(a.agency_id||"");
                  const ast = a.subscription_status || "";
                  const isEditing = _adminEditSub && _adminEditSub.agencyId === (a.agency_id||"");
                  const daysLeft = _adminDaysLeft(a.subscription_expires_at);
                  const isBlocked = ast === "blocked";
                  const isExpired = ast === "expired";
                  return `
                    <div style="border:1px solid var(--line);border-radius:14px;overflow:hidden;${isBlocked?"opacity:.6":""}">
                      <!-- User row -->
                      <div style="display:flex;align-items:center;gap:12px;padding:14px 16px;flex-wrap:wrap">
                        <!-- Avatar -->
                        <div style="width:36px;height:36px;border-radius:50%;background:var(--primary);display:grid;place-items:center;font-size:14px;font-weight:900;color:#fff;flex-shrink:0">
                          ${(a.email||"?")[0].toUpperCase()}
                        </div>
                        <!-- Info -->
                        <div class="u-flex1-min0">
                          <div style="font-size:13px;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escapeHtml(a.email||"—")}</div>
                          <div style="font-size:12px;color:var(--muted);margin-top:2px">
                            Зарег.: ${a.created_at ? new Date(a.created_at).toLocaleDateString("ru-RU") : "—"}
                            ${a.last_sign_in_at ? ` · Вход: ${new Date(a.last_sign_in_at).toLocaleDateString("ru-RU")}` : ""}
                          </div>
                        </div>
                        <!-- Status + plan + expiry -->
                        <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;flex-shrink:0">
                          <span style="padding:3px 10px;border-radius:99px;font-size:12px;font-weight:700;background:${statusColor[ast]||"var(--panel2)"};color:${statusText[ast]||"var(--muted)"}">
                            ${_adminSubLabel(ast)}
                          </span>
                          ${a.subscription_plan ? `<span style="font-size:12px;font-weight:600;color:var(--muted)">${_adminPlanLabel(a.subscription_plan)}</span>` : ""}
                          ${a.subscription_expires_at ? `<span style="font-size:12px;color:${isExpired?"var(--red)":"var(--muted)"}">${daysLeft}</span>` : ""}
                          ${!a.email_confirmed ? `<span title="Email не подтверждён" style="font-size:12px;color:var(--yellow);display:inline-flex">${icon("warning", 13)}</span>` : ""}
                        </div>
                        <!-- Actions -->
                        <div style="display:flex;gap:6px;flex-shrink:0">
                          ${!isEditing ? `
                            ${(isExpired || ast === "") ? `<button class="btn small green" onclick="app.adminActivate('${aid}')" title="Активировать на 30 дней">${icon("check")} Активировать</button>` : ""}
                            <button class="btn small" onclick="app.adminExtendTrial('${aid}')" title="+14 дней к триалу">+14д</button>
                            <button class="btn small" onclick="app._openEditSub('${aid}','${escapeHtml(ast)}','${escapeHtml(a.subscription_plan||"")}','${a.subscription_expires_at ? a.subscription_expires_at.slice(0,10) : ""}')" title="Изменить подписку" aria-label="Изменить подписку">${icon("pencil")}</button>
                            <button class="btn small ${isBlocked?"green":"danger"}" onclick="app.adminToggleBlock('${aid}','${escapeHtml(ast)}')" title="${isBlocked?"Разблокировать":"Заблокировать"}" aria-label="${isBlocked?"Разблокировать":"Заблокировать"}">${isBlocked?icon("unlock"):icon("xcircle")}</button>
                          ` : `
                            <button class="btn small" onclick="app._closeEditSub()" style="opacity:.6">Отмена</button>
                          `}
                        </div>
                      </div>
                      <!-- Inline editor -->
                      ${isEditing ? `
                        <div style="border-top:1px solid var(--line);padding:14px 16px;background:var(--panel2)">
                          <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px;margin-bottom:12px">
                            <div class="field" style="margin:0">
                              <label>Статус</label>
                              <select onchange="app._setEditSub('status',this.value)">
                                ${["trial","active","expired","blocked"].map(sv => `<option value="${sv}" ${_adminEditSub.status===sv?"selected":""}>${_adminSubLabel(sv)}</option>`).join("")}
                              </select>
                            </div>
                            <div class="field" style="margin:0">
                              <label>Тариф</label>
                              <select onchange="app._setEditSub('plan',this.value)">
                                ${["month1","month3","month6","year","pro"].map(pv => `<option value="${pv}" ${_adminEditSub.plan===pv?"selected":""}>${_adminPlanLabel(pv)}</option>`).join("")}
                              </select>
                            </div>
                            <div class="field" style="margin:0">
                              <label>Истекает</label>
                              <input type="date" value="${escapeHtml(_adminEditSub.expires||"")}" onchange="app._setEditSub('expires',this.value)">
                            </div>
                          </div>
                          <div class="u-flex-g8">
                            <button class="btn primary small" onclick="app.adminSetSubscription()">Сохранить</button>
                            <button class="btn small" onclick="app._closeEditSub()">Отмена</button>
                          </div>
                        </div>
                      ` : ""}
                    </div>`;
                }).join("")}
              </div>
            ` : ""}

            <!-- Promos tab -->
            ${_adminPanelTab === "promos" ? `
              <div style="background:var(--panel2);border:1px solid var(--line);border-radius:14px;padding:20px;margin-bottom:16px">
                <h3 style="margin:0 0 16px;font-size:15px">+ Новый промокод</h3>
                ${_adminPromoForm.error ? `<div style="color:var(--red);font-size:13px;margin-bottom:10px;padding:8px 12px;background:rgba(220,38,38,.1);border-radius:8px">${escapeHtml(_adminPromoForm.error)}</div>` : ""}
                <div style="display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:10px;margin-bottom:12px">
                  ${field("Код", `<input placeholder="PROMO2026" value="${escapeHtml(_adminPromoForm.code)}" oninput="app._setPromoForm('code',this.value)" style="text-transform:uppercase">`)}
                  ${field("Скидка %", `<input type="number" min="1" max="100" placeholder="20" value="${_adminPromoForm.discount||""}" oninput="app._setPromoForm('discount',this.value)">`)}
                  ${field("Макс. исп.", `<input type="number" min="1" value="${_adminPromoForm.maxUses||100}" oninput="app._setPromoForm('maxUses',this.value)">`)}
                  ${field("Истекает", `<input type="date" value="${escapeHtml(_adminPromoForm.expires||"")}" onchange="app._setPromoForm('expires',this.value)">`)}
                </div>
                <button class="btn primary" onclick="app.adminCreatePromo()" ${_adminPromoForm.loading?"disabled":""} style="display:flex;align-items:center;gap:6px">
                  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><path d="M12 5v14M5 12h14"/></svg>
                  ${_adminPromoForm.loading?"Создание...":"Создать промокод"}
                </button>
              </div>
              ${(_adminPromoCodes||[]).length ? `
                <div style="display:flex;flex-direction:column;gap:8px">
                  ${(_adminPromoCodes||[]).map(p => `
                    <div style="display:flex;align-items:center;gap:12px;padding:12px 16px;border:1px solid var(--line);border-radius:12px;${p.active===false?"opacity:.55":""}">
                      <div class="u-flex1-min0">
                        <div style="display:flex;align-items:center;gap:8px">
                          <span style="font-family:monospace;font-size:14px;font-weight:900">${escapeHtml(p.code)}</span>
                          <span style="font-size:13px;font-weight:700;color:#a78bfa">${p.discount||0}%</span>
                          <span style="padding:2px 8px;border-radius:99px;font-size:12px;font-weight:700;background:${p.active!==false?"rgba(22,163,74,.12)":"rgba(220,38,38,.1)"};color:${p.active!==false?"#4ade80":"var(--red)"}">
                            ${p.active!==false?"Активен":"Отключён"}
                          </span>
                        </div>
                        <div style="font-size:12px;color:var(--muted);margin-top:4px">
                          Использован: ${p.uses||0} / ${p.max_uses||"∞"}
                          ${p.expires_at ? ` · до ${new Date(p.expires_at).toLocaleDateString("ru-RU")}` : ""}
                        </div>
                      </div>
                      <button class="btn small ${p.active!==false?"danger":""}" onclick="app.adminTogglePromo('${p.id}',${p.active===false})">
                        ${p.active!==false?"Откл.":"Вкл."}
                      </button>
                    </div>`).join("")}
                </div>
              ` : `<div style="text-align:center;padding:24px;color:var(--muted)">Промокодов пока нет</div>`}
            ` : ""}

            <!-- Errors tab -->
            ${_adminPanelTab === "errors" ? (() => {
              const rows = _adminErrors || [];
              const last24h = rows.filter(r => Date.now() - new Date(r.created_at).getTime() < 86400000).length;
              const agenciesAffected = new Set(rows.filter(r => r.agency_id).map(r => r.agency_id)).size;
              const groups = _adminErrorGroups();
              return `
                <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:10px;margin-bottom:16px">
                  ${_adminStatCard("Всего записей", rows.length, "")}
                  ${_adminStatCard("За 24ч", last24h, last24h > 0 ? "yellow" : "green")}
                  ${_adminStatCard("Уникальных", groups.length, "blue")}
                  ${_adminStatCard("Агентств задето", agenciesAffected, "purple")}
                </div>
                <div style="display:flex;gap:10px;margin-bottom:16px;flex-wrap:wrap">
                  <input type="text" placeholder="Поиск по тексту ошибки..." value="${escapeHtml(_adminErrorsFilter.q)}"
                    oninput="app._setErrorsFilter('q',this.value)" style="flex:1;min-width:180px">
                  <select onchange="app._setErrorsFilter('kind',this.value)">
                    <option value="">Все типы</option>
                    <option value="error" ${_adminErrorsFilter.kind === "error" ? "selected" : ""}>error</option>
                    <option value="promise" ${_adminErrorsFilter.kind === "promise" ? "selected" : ""}>promise</option>
                  </select>
                </div>
                ${groups.length ? groups.map(g => {
                  const expanded = _adminErrorExpanded === g.key;
                  return `
                    <div style="border:1px solid var(--line);border-radius:12px;margin-bottom:8px;overflow:hidden">
                      <button data-key="${escapeHtml(g.key)}" onclick="app._toggleErrorGroup(this.dataset.key)"
                        style="width:100%;text-align:left;background:none;border:none;cursor:pointer;padding:12px 16px;display:flex;align-items:center;gap:10px">
                        <span style="padding:2px 8px;border-radius:99px;font-size:11px;font-weight:700;flex-shrink:0;
                          background:${g.kind === "error" ? "rgba(220,38,38,.12)" : "rgba(234,88,12,.12)"};
                          color:${g.kind === "error" ? "var(--text-danger)" : "var(--text-warning)"}">${g.kind}</span>
                        <span class="u-flex1-min0" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px;font-family:var(--font-mono)">${escapeHtml(g.message || "")}</span>
                        <span style="font-size:12px;font-weight:800;color:var(--muted);flex-shrink:0">×${g.count}</span>
                        ${g.agencies.size ? `<span style="font-size:12px;color:var(--muted);flex-shrink:0">${g.agencies.size} аг.</span>` : ""}
                        <span style="font-size:11px;color:var(--hint);flex-shrink:0">${expanded ? "▲" : "▼"}</span>
                      </button>
                      ${expanded ? `
                        <div style="border-top:1px solid var(--line);padding:12px 16px;background:var(--panel2);display:flex;flex-direction:column;gap:8px;max-height:320px;overflow-y:auto">
                          ${g.rows.slice(0, 30).map(r => {
                            const email = _agencyEmailById(r.agency_id);
                            return `
                            <div style="font-size:12px;color:var(--muted);border-bottom:1px solid var(--line);padding-bottom:6px">
                              ${new Date(r.created_at).toLocaleString("ru-RU")}
                              ${r.source ? ` · ${escapeHtml(r.source)}` : ""}
                              ${r.agency_id ? ` · ${email ? escapeHtml(email) : "аг. " + escapeHtml(r.agency_id.slice(0, 8)) + "…"}` : " · аноним"}
                            </div>`;
                          }).join("")}
                          ${g.rows.length > 30 ? `<div style="font-size:12px;color:var(--muted)">...ещё ${g.rows.length - 30}</div>` : ""}
                        </div>
                      ` : ""}
                    </div>`;
                }).join("") : `<div style="text-align:center;padding:24px;color:var(--muted)">${rows.length ? "Ничего не найдено по фильтру" : "Ошибок нет"}</div>`}
              `;
            })() : ""}
          </div>`;
      }

      function _adminStatCard(label, value, color) {
        const colors = { green: "rgba(22,163,74,.12)", yellow: "rgba(202,138,4,.12)", blue: "rgba(37,99,235,.12)", purple: "rgba(124,58,237,.12)", "": "var(--panel2)" };
        return `<div class="panel" style="background:${colors[color]||"var(--panel2)"};box-shadow:none;padding:18px">
          <div style="font-size:22px;font-weight:900;font-variant-numeric:tabular-nums">${value}</div>
          <div style="font-size:12px;color:var(--muted);margin-top:4px">${label}</div>
        </div>`;
      }

      function _setAdminTab(tab) { _adminPanelTab = tab; render(); }
      function _setSettingsTab(tab) { _settingsTab = tab; render(); }
      function _setErrorsFilter(k, v) { _adminErrorsFilter[k] = v; render(); }
      function _toggleErrorGroup(key) { _adminErrorExpanded = _adminErrorExpanded === key ? null : key; render(); }
      function _agencyEmailById(agencyId) {
        if (!agencyId) return null;
        const a = (_adminAgencies || []).find(x => x.agency_id === agencyId);
        return a ? a.email : null;
      }
      // Группировка сырых client_errors по (kind + первые 120 символов сообщения) —
      // одна и та же ошибка у разных юзеров/сессий иначе тонет в списке дублей
      function _adminErrorGroups() {
        const rows = _adminErrors || [];
        const q = (_adminErrorsFilter.q || "").toLowerCase().trim();
        const kindF = _adminErrorsFilter.kind || "";
        const filtered = rows.filter(r =>
          (!kindF || r.kind === kindF) &&
          (!q || (r.message || "").toLowerCase().includes(q))
        );
        const map = new Map();
        for (const r of filtered) {
          const key = r.kind + "|" + (r.message || "").slice(0, 120);
          if (!map.has(key)) {
            map.set(key, { key, kind: r.kind, message: r.message, count: 0, lastSeen: r.created_at, agencies: new Set(), rows: [] });
          }
          const g = map.get(key);
          g.count++;
          g.rows.push(r);
          if (r.agency_id) g.agencies.add(r.agency_id);
          if (r.created_at > g.lastSeen) g.lastSeen = r.created_at;
        }
        return Array.from(map.values()).sort((a, b) => b.count - a.count);
      }
      function _openEditSub(agencyId, status, plan, expires) { _adminEditSub = { agencyId, status, plan, expires }; render(); }
      function _closeEditSub() { _adminEditSub = null; render(); }
      function _setEditSub(k, v) { if (_adminEditSub) { _adminEditSub[k] = v; render(); } }
      function _setPromoForm(k, v) { _adminPromoForm[k] = v; render(); }

