          month3: ["Всё из «Месяца»", `До ${PAID_MAX_USERS} пользователей`, "Экономия 20%", "Один платёж на 3 месяца", "Поддержка"],
          month6: ["Всё из «Месяца»", `До ${PAID_MAX_USERS} пользователей`, "Экономия 31%", "Один платёж на полгода", "Поддержка"],
