          const btnLabel = isCurrent ? "✓ Активен" : isLoading ? "⏳..." : p.price === 0 ? "Бесплатно" : `Оплатить ${payAmount} ₽${p.months > 1 ? ` за ${p.months} мес.` : ""}`;
