      function renderProfile() {
        const email = _adminSession ? _adminSession.user.email : "";
        const sub = _userProfile;
        const subLabel = getSubscriptionLabel();
        const active = isSubscriptionActive();
        const initial = email ? email[0].toUpperCase() : "A";
        const us = getUserSettings();
        const displayName = us.displayName || "";
        const avatarHtml = us.avatarDataUrl
          ? `<img src="${safeAvatarSrc(us.avatarDataUrl)}" style="width:100%;height:100%;object-fit:cover;border-radius:50%">`
          : `<span style="font-size:26px;font-weight:900">${escapeHtml(initial)}</span>`;

        // Subscription status details
        let subStatusBlock = "";
        if (sub) {
          const exp = sub.subscription_expires_at ? new Date(sub.subscription_expires_at) : null;
          const daysLeft = exp ? Math.max(0, Math.round((exp - new Date()) / 86400000)) : null;
          const expStr = exp ? exp.toLocaleDateString("ru-RU", { day: "2-digit", month: "long", year: "numeric" }) : "";
          const s = sub.subscription_status;
          const planLabel = { trial: "Пробный период", month1: "Месяц", month3: "3 месяца", month6: "6 месяцев", year: "Год", pro: "PRO" }[sub.subscription_plan] || sub.subscription_plan || "PRO";

          if (s === "active") {
            subStatusBlock = `
              <div style="background:rgba(22,163,74,.1);border:1px solid rgba(22,163,74,.3);border-radius:14px;padding:16px 20px;margin-bottom:20px">
                <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px">
                  <span style="color:var(--green);flex-shrink:0">${icon("check", 20)}</span>
                  <div>
                    <div style="font-weight:900;font-size:15px;color:var(--green)">Подписка активна — ${escapeHtml(planLabel)}</div>
                    ${exp ? `<div style="font-size:12px;color:var(--muted);margin-top:2px">Действует до: ${escapeHtml(expStr)}${daysLeft !== null ? ` (ещё ${daysLeft} дн.)` : ""}</div>` : ""}
                  </div>
                </div>
              </div>`;
          } else if (s === "trial") {
            const urgency = daysLeft !== null && daysLeft <= 3;
            subStatusBlock = `
              <div style="background:rgba(202,138,4,.1);border:1px solid rgba(202,138,4,.3);border-radius:14px;padding:16px 20px;margin-bottom:20px">
                <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px">
                  <span style="color:${urgency ? "var(--red)" : "var(--yellow)"};flex-shrink:0">${icon("warning", 20)}</span>
                  <div>
                    <div style="font-weight:900;font-size:15px;color:${urgency ? "var(--red)" : "var(--yellow)"}">Пробный период${daysLeft !== null ? ` — осталось ${daysLeft} дн.` : ""}</div>
                    ${exp ? `<div style="font-size:12px;color:var(--muted);margin-top:2px">Истекает: ${escapeHtml(expStr)}</div>` : ""}
                  </div>
                </div>
                <p style="font-size:13px;margin:0;color:var(--muted)">После окончания пробного периода выберите тариф ниже, чтобы продолжить работу.</p>
              </div>`;
          } else {
            subStatusBlock = `
              <div style="background:rgba(220,38,38,.1);border:1px solid rgba(220,38,38,.3);border-radius:14px;padding:16px 20px;margin-bottom:20px">
                <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px;color:var(--red);font-weight:900">${icon("xcircle")} Подписка истекла</div>
                <p style="font-size:13px;margin:0;color:var(--muted)">Выберите тариф ниже для продолжения работы.</p>
              </div>`;
          }
        }

        return `
          <div class="panel">
            ${_adminSession ? `
            <!-- ── PROFILE SECTION ── -->
            <div class="section-title" style="margin-bottom:20px">
              <div><h1 class="m-0">Профиль</h1><p style="margin:4px 0 0;color:var(--muted)">Аккаунт, подписка и настройки</p></div>
              <div class="toolbar" style="gap:8px">
                <button class="btn small green" onclick="app.forceSaveToCloud()">${icon("cloud")} Синхронизировать</button>
                <button class="btn small" onclick="app.adminLogout()">→ Выйти</button>
              </div>
            </div>

            <!-- Avatar + name -->
            <div class="panel" style="box-shadow:none;background:var(--panel2);margin-bottom:16px">
              <h2 style="margin-top:0;font-size:15px">Фото и имя</h2>
              <div style="display:flex;align-items:center;gap:18px;flex-wrap:wrap">
                <div style="position:relative;flex:0 0 80px">
                  <div style="width:80px;height:80px;border-radius:50%;background:var(--primary);display:flex;align-items:center;justify-content:center;color:#fff;overflow:hidden;box-shadow:0 6px 20px rgba(124,58,237,.35)">
                    ${avatarHtml}
                  </div>
                </div>
                <div style="flex:1;min-width:180px">
                  <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px">
                    <label class="btn small" style="cursor:pointer;display:inline-flex;align-items:center;gap:6px">
                      <span style="color:var(--primary);display:inline-flex">${icon("camera")}</span> Изменить фото
                      <input type="file" accept="image/*" onchange="app.uploadUserAvatar(event)" style="display:none">
                    </label>
                    ${us.avatarDataUrl ? `<button class="btn small danger" onclick="app.removeUserAvatar()">${TRASH_SVG} Удалить</button>` : ""}
                  </div>
                  <div class="grid two" style="gap:8px">
                    <div class="field" style="margin:0">
                      <label>Имя</label>
                      <input placeholder="Ваше имя" value="${escapeHtml(us.displayName||"")}" oninput="app._saveUserField('displayName',this.value)">
                    </div>
                    <div class="field" style="margin:0">
                      <label>Email</label>
                      <input value="${escapeHtml(email)}" readonly style="opacity:.6">
                    </div>
                  </div>
                </div>
              </div>
            </div>

            ${subStatusBlock}

            <!-- Compact subscription link -->
            <div class="panel" style="box-shadow:none;background:var(--panel2);margin-bottom:16px">
              <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px">
                <div>
                  <h2 style="margin:0 0 4px;font-size:15px;display:flex;align-items:center;gap:9px">${iconBadge("card", "var(--primary)")} Тарифный план</h2>
                  <div class="u-meta-13">${escapeHtml(subLabel)}${sub && sub.subscription_expires_at ? ` · до ${new Date(sub.subscription_expires_at).toLocaleDateString("ru-RU", {day:"2-digit",month:"short",year:"numeric"})}` : ""}</div>
                </div>
                <button class="btn small primary" onclick="app.go('plans')" style="white-space:nowrap">Изменить тариф</button>
              </div>
            </div>

            <!-- Security -->
            <div class="panel" style="box-shadow:none;background:var(--panel2);margin-bottom:16px">
              <h2 style="margin-top:0;font-size:15px;display:flex;align-items:center;gap:9px">${iconBadge("lock", "var(--blue)")} Безопасность</h2>
              <div id="changePasswordBox"></div>
              <div class="toolbar" style="gap:8px;flex-wrap:wrap">
                <button class="btn small" onclick="app.openChangePassword()" style="display:inline-flex;align-items:center;gap:6px"><span style="color:var(--blue);display:inline-flex">${icon("key")}</span> Изменить пароль</button>
                <button class="btn small danger" onclick="app.confirmDeleteAccount()">${TRASH_SVG} Удалить аккаунт</button>
              </div>
            </div>

            <!-- Team -->
            ${(() => {
              const agencyId = getAgencyId();
              const isOwner = _adminSession && _userProfile && _userProfile.agency_id === _adminSession.user.id;
              const onlineList = _onlineUsers.length ? _onlineUsers.map(u => `<span style="background:rgba(22,163,74,.12);border:1px solid rgba(22,163,74,.3);border-radius:99px;padding:2px 10px;font-size:12px">● ${escapeHtml(u)}</span>`).join(" ") : "";
              return `
              <div class="panel" style="box-shadow:none;background:var(--panel2);margin-bottom:16px">
                <h2 style="margin-top:0;font-size:15px;display:flex;align-items:center;gap:9px">${iconBadge("users", "var(--green)")} Команда</h2>
                ${isOwner ? `
                  <p style="font-size:13px;color:var(--muted);margin:0 0 10px">Дайте этот код коллеге — при регистрации он вводит его и попадёт в ваше агентство.</p>
                  <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
                    <code style="flex:1;font-size:12px;background:rgba(0,0,0,.2);border-radius:8px;padding:8px 12px;border:1px solid var(--line);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0">${escapeHtml(agencyId)}</code>
                    <button class="btn small" onclick="app.copy('${escapeHtml(agencyId)}','Скопировано!')" style="display:inline-flex;align-items:center;gap:6px;white-space:nowrap"><span style="color:var(--primary);display:inline-flex">${icon("copy")}</span> Копировать</button>
                  </div>
                  ${onlineList ? `<div style="margin-top:10px;display:flex;gap:6px;flex-wrap:wrap;align-items:center"><span class="u-meta">Сейчас онлайн:</span>${onlineList}</div>` : ""}
                ` : `<p style="font-size:13px;color:var(--muted);margin:0">Вы в команде агентства${onlineList ? ` · Онлайн: ${onlineList}` : ""}</p>`}
              </div>`;
            })()}
            ` : `
            <div style="text-align:center;padding:32px 24px;margin-bottom:24px;background:var(--panel2);border-radius:16px;border:1px solid var(--line)">
              <div style="width:72px;height:72px;border-radius:50%;background:var(--primary);display:flex;align-items:center;justify-content:center;font-size:30px;font-weight:900;color:#fff;margin:0 auto 16px;box-shadow:0 8px 28px rgba(124,58,237,.4)">A</div>
              <h2 style="margin:0 0 6px;font-size:20px">Войдите в ADERVIS CRM</h2>
              <p style="color:var(--muted);margin:0 0 18px;font-size:14px">Облачное хранение · Синхронизация · Подписка</p>
              <button class="btn primary" onclick="app.exitLocalModeAndLogin()" style="padding:12px 28px;font-size:15px;width:100%;max-width:280px;display:inline-flex;align-items:center;justify-content:center;gap:8px">${icon("lock")} Войти / Зарегистрироваться</button>
              <p style="font-size:12px;color:var(--muted);margin:12px 0 0">7 дней бесплатно · Без карты · Данные не удаляются</p>
            </div>
            `}

            <!-- Referral program -->
            ${_adminSession ? (() => {
              // Загружаем статистику асинхронно после рендера
              setTimeout(_loadRefStats, 200);
              const refUrl = escapeHtml(location.origin + location.pathname + '?ref=' + getAgencyId());
              return `
              <div class="panel" style="box-shadow:none;background:var(--panel2);margin-bottom:16px">
                <h2 style="margin-top:0;font-size:15px;display:flex;align-items:center;gap:9px">${iconBadge("gift", "var(--orange)")} Реферальная программа</h2>
                <p style="font-size:13px;color:var(--muted);margin:0 0 12px;line-height:1.6">
                  Поделитесь ссылкой с другой видеостудией или фрилансером. Когда они оплатят любой тариф — вы получите <b>+30 дней</b> к подписке бесплатно.
                </p>
                <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:12px">
                  <code id="refLinkCode" style="flex:1;font-size:12px;background:rgba(0,0,0,.2);border-radius:8px;padding:8px 12px;border:1px solid var(--line);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0;color:var(--text2)">${refUrl}</code>
                  <button class="btn small" onclick="app.copy(document.getElementById('refLinkCode').textContent.trim(),'Реферальная ссылка скопирована!')" style="display:inline-flex;align-items:center;gap:6px;white-space:nowrap"><span style="color:var(--primary);display:inline-flex">${icon("copy")}</span> Копировать</button>
                </div>
                <div id="refStats" class="u-meta" aria-busy="true"><div class="skeleton" style="height:14px;width:240px"></div></div>
              </div>`;
            })() : ''}

          <div class="panel" style="box-shadow:none;background:var(--panel2);margin-top:16px">
            <h2 style="margin-top:0;font-size:15px;margin-bottom:14px">Что включено в подписку</h2>
            <div class="grid two" style="gap:10px">
              ${[
                ["CRM и сделки", "Неограниченное число сделок и проектов по всем стадиям воронки"],
                ["Калькулятор смет", "100+ позиций каталога: съёмка, постпродакшн, ИИ, логистика"],
                ["КП и договоры", "Генерация коммерческих предложений и договоров за секунды"],
                ["Календарь", "Дедлайны, задачи и платежи по всем проектам в одном месте"],
                ["Финансы", "Доходы, расходы, маржа и аналитика по каждому проекту"],
                ["Облачная синхронизация", "Realtime-синхронизация между устройствами и членами команды"],
                ["Команда", "Совместная работа — пригласите коллег через код приглашения"],
                ["Мобильная версия", "PWA — устанавливается на телефон и работает как приложение"]
              ].map(([title, desc]) => `
                <div style="display:flex;gap:10px;align-items:flex-start;padding:10px;background:var(--panel);border-radius:10px;border:1px solid var(--line)">
                  <div style="width:8px;height:8px;border-radius:50%;background:var(--primary);flex-shrink:0;margin-top:5px"></div>
                  <div>
                    <div style="font-size:13px;font-weight:700;margin-bottom:2px">${escapeHtml(title)}</div>
                    <div class="u-meta">${escapeHtml(desc)}</div>
                  </div>
                </div>`).join("")}
            </div>
          </div>

          </div>
        `;
      }

      /* ─── YOOKASSA SUBSCRIPTION PAYMENT ─── */
      async function buyPlan(planId) {
        if (!_adminSession) { toast("Войдите в аккаунт для оплаты"); return; }
        if (planId === "trial" || _buyingPlan) return;

        _buyingPlan = planId;
        render();
        // Авто-сброс если платёж завис (нет ответа 30 сек)
        const _buyTimeout = setTimeout(() => { if (_buyingPlan === planId) { _buyingPlan = null; render(); } }, 30000);

        try {
          const { url } = getSupabaseConfig();
          const resp = await fetch(`${url}/functions/v1/create-payment`, {
            method: "POST",
            headers: {
              "Content-Type":  "application/json",
              "Authorization": `Bearer ${_adminSession.access_token}`,
            },
            body: JSON.stringify({
              planId,
              promoCode: (_promoState && _promoState.code) ? _promoState.code : undefined,
            }),
          });

          if (!resp.ok) {
            const err = await resp.json().catch(() => ({ error: "Ошибка сети" }));
            throw new Error(err.error || "Ошибка создания платежа");
          }

          const { paymentUrl } = await resp.json();
          clearTimeout(_buyTimeout);
          trackGoal("payment_click", { planId });
          window.location.href = paymentUrl;
        } catch (e) {
          clearTimeout(_buyTimeout);
          toast("Ошибка оплаты: " + e.message);
          _buyingPlan = null;
          render();
        }
      }

      async function validatePromo() {
        const code = _promoCode.trim().toUpperCase();
        if (!code || !_supabase) return;
        _promoState = "checking";
        render();
        try {
          const { data, error } = await _supabase
            .from("promo_codes")
            .select("code,discount_percent,max_uses,uses_count,expires_at")
            .eq("code", code)
            .eq("is_active", true)
            .single();
          if (error || !data) {
            _promoState = "invalid";
          } else if (data.max_uses !== null && data.uses_count >= data.max_uses) {
            _promoState = "invalid";
          } else if (data.expires_at && new Date(data.expires_at) < new Date()) {
            _promoState = "invalid";
          } else {
            _promoState = { code: data.code, discount: data.discount_percent };
          }
        } catch (e) {
          _promoState = "invalid";
        }
        render();
      }

      function clearPromo() {
        _promoCode = "";
        _promoState = null;
        render();
      }

      function gotoSubscription() {
        go("plans");
      }

      function checkPaymentReturn() {
        const params = new URLSearchParams(window.location.search);
        if (params.get("payment") !== "success") return;
        history.replaceState({}, "", window.location.pathname);
        toast("⏳ Проверяем статус оплаты...");
        setTimeout(async () => {
          if (_adminSession) {
            await _loadUserProfile(_adminSession.user.id, _adminSession.user.email);
            render();
            if (isSubscriptionActive()) {
              trackGoal("payment_success", { planId: _userProfile && _userProfile.subscription_plan });
              toast("🎉 Подписка активирована! Спасибо за оплату.");
            } else {
              toast("Оплата обрабатывается — статус обновится автоматически.");
            }
          }
        }, 2500);
      }

      /* ═══════════════════════════════════════════════════════
         GOOGLE CALENDAR — личное подключение (двусторонняя синхронизация)
      ═══════════════════════════════════════════════════════ */
      async function _loadGoogleCalendarStatus() {
        if (!_supabase || !_adminSession) { _googleCalStatus = null; return; }
        try {
          const { data, error } = await _supabase
            .from("google_calendar_connections")
            .select("google_email,connected_at")
            .eq("user_id", _adminSession.user.id)
            .maybeSingle();
          if (error) throw error;
          _googleCalStatus = data ? { connected: true, email: data.google_email || "" } : { connected: false };
        } catch (e) {
          _googleCalStatus = { connected: false };
        }
        render();
        // Приложение может открыться сразу на календаре (state.view восстановлен из
        // прошлой сессии) — тогда go('global-calendar') не сработает, подгружаем сами.
        if (_googleCalStatus.connected && (state.view === "calendar" || state.view === "global-calendar")) {
          loadGoogleCalendarEvents();
        }
      }

      async function connectGoogleCalendar() {
        if (!_adminSession) { toast("Войдите в аккаунт"); return; }
        const btn = document.getElementById("googleCalConnectBtn");
        if (btn) { btn.disabled = true; btn.textContent = "⏳ Подключение..."; }
        try {
          const { url } = getSupabaseConfig();
          const resp = await fetch(`${url}/functions/v1/google-calendar-connect`, {
            method: "POST",
            headers: { "Content-Type": "application/json", "Authorization": `Bearer ${_adminSession.access_token}` },
          });
          const data = await resp.json();
          if (!resp.ok || !data.authUrl) throw new Error(data.error || "Не удалось подключить Google Calendar");
          location.href = data.authUrl;
        } catch (e) {
          toast("Ошибка: " + e.message);
          if (btn) { btn.disabled = false; btn.textContent = "🔗 Подключить Google Calendar"; }
        }
      }

      async function disconnectGoogleCalendar() {
        if (!_adminSession) return;
        try {
          const { error } = await _supabase.from("google_calendar_connections").delete().eq("user_id", _adminSession.user.id);
          if (error) throw error;
          _googleCalStatus = { connected: false };
          _googleCalEvents = [];
          toast("Google Calendar отключён");
          render();
        } catch (e) {
          toast("Ошибка отключения: " + e.message);
        }
      }

      function checkGoogleCalendarReturn() {
        const params = new URLSearchParams(window.location.search);
        const connected = params.get("google_connected");
        const err = params.get("google_calendar_error");
        if (!connected && !err) return;
        history.replaceState({}, "", window.location.pathname);
        if (connected) {
          toast("✅ Google Calendar подключён");
          _loadGoogleCalendarStatus();
        } else {
          toast("⚠️ Не удалось подключить Google Calendar (" + err + ")");
        }
      }

      // Кэш на минуту — renderCalendar() может вызываться очень часто (любой render()),
      // сам fetch запускается только из go('calendar') и после подключения/отключения.
      async function loadGoogleCalendarEvents(force) {
        if (!_adminSession || !_googleCalStatus || !_googleCalStatus.connected) return;
        if (!force && Date.now() - _googleCalEventsLoadedAt < 60000) return;
        try {
          const { url } = getSupabaseConfig();
          const resp = await fetch(`${url}/functions/v1/google-calendar-events`, {
            method: "POST",
            headers: { "Content-Type": "application/json", "Authorization": `Bearer ${_adminSession.access_token}` },
          });
          const data = await resp.json();
          if (data.needsReconnect) {
            _googleCalStatus = { connected: false };
            toast("⚠️ Доступ к Google Calendar истёк — подключите заново в Настройках");
          } else if (Array.isArray(data.events)) {
            _googleCalEvents = data.events;
          } else if (data.error) {
            console.error("loadGoogleCalendarEvents:", data);
          }
          _googleCalEventsLoadedAt = Date.now();
          render();
        } catch (e) { /* Google Calendar недоступен — CRM-календарь работает и без него */ }
      }

      // googleEventIds — объект { [user_id]: eventId }, т.к. у каждого залогиненного
      // пользователя свой личный Google Calendar (см. normalizeTask/normalizeSavedProject).
      function _myGoogleEventId(obj) {
        return _adminSession ? (obj?.googleEventIds || {})[_adminSession.user.id] || "" : "";
      }

      // Общее ядро upsert-запроса к google-calendar-sync-task — используется и ручными
      // кнопками (syncTaskToGoogle и т.п.), и тихой автосинхронизацией ниже, чтобы разбор
      // ответа (needsReconnect и т.д.) не дублировался в 4+ местах.
      async function _pushGoogleEvent(id, title, deadline, currentEventId) {
        const { url } = getSupabaseConfig();
        const resp = await fetch(`${url}/functions/v1/google-calendar-sync-task`, {
          method: "POST",
          headers: { "Content-Type": "application/json", "Authorization": `Bearer ${_adminSession.access_token}` },
          body: JSON.stringify({ action: "upsert", task: { id, title, deadline, googleEventId: currentEventId } }),
        });
        const data = await resp.json();
        if (!resp.ok) throw new Error(data.error || "Ошибка синхронизации");
        if (data.needsReconnect) { _googleCalStatus = { connected: false }; throw new Error("Доступ к Google Calendar истёк — переподключите в Настройках"); }
        return data.googleEventId;
      }

      // Тихая автосинхронизация — вызывается из createTask/updateTask/saveTaskModal при
      // установке или изменении дедлайна задачи, без клика на кнопку. Если Google Calendar
      // не подключён — молча ничего не делает, ручные кнопки остаются как fallback.
      async function _autoSyncTaskToGoogle(task) {
        if (!_googleCalStatus || !_googleCalStatus.connected || !_adminSession || !task.deadline) return;
        try {
          const googleEventId = await _pushGoogleEvent(task.id, task.title, task.deadline, _myGoogleEventId(task));
          const live = _findLiveTaskById(task.id);
          if (live) { live.googleEventIds = { ...(live.googleEventIds || {}), [_adminSession.user.id]: googleEventId }; save(); render(); }
          toast("📅 Задача синхронизирована с Google Calendar");
        } catch (e) {
          toast("⚠️ Google Calendar: " + e.message);
        }
      }

      // Тот же принцип, для дедлайна сделки (state.project.deadline) — из updateProject.
      async function _autoSyncProjectDeadlineToGoogle() {
        if (!_googleCalStatus || !_googleCalStatus.connected || !_adminSession) return;
        if (!state.activeProjectId || !state.project.deadline) return;
        try {
          const googleEventId = await _pushGoogleEvent(state.activeProjectId, `Дедлайн: ${state.project.name}`, state.project.deadline, _myGoogleEventId(state.project));
          const nextIds = { ...(state.project.googleEventIds || {}), [_adminSession.user.id]: googleEventId };
          state.project.googleEventIds = nextIds;
          const saved = state.savedProjects.find(p => p.id === state.activeProjectId);
          if (saved) saved.googleEventIds = nextIds;
          save();
          toast("📅 Дедлайн синхронизирован с Google Calendar");
          render();
        } catch (e) {
          toast("⚠️ Google Calendar: " + e.message);
        }
      }

      async function _deleteGoogleCalendarEvent(entity) {
        const eventId = _myGoogleEventId(entity);
        if (!_adminSession || !eventId) return;
        try {
          const { url } = getSupabaseConfig();
          await fetch(`${url}/functions/v1/google-calendar-sync-task`, {
            method: "POST",
            headers: { "Content-Type": "application/json", "Authorization": `Bearer ${_adminSession.access_token}` },
            body: JSON.stringify({ action: "delete", task: { id: entity.id, googleEventId: eventId } }),
          });
        } catch (e) { /* не критично */ }
      }

      async function syncTaskModalToGoogle() {
        const m = state.taskModal;
        if (!m) return;
        if (!_googleCalStatus || !_googleCalStatus.connected) { toast("Сначала подключите Google Calendar в Настройках"); return; }
        if (!m.deadline) { toast("Сначала укажите дедлайн задачи"); return; }
        const persisted = _commitTaskModal();
        if (!persisted) return;
        const btn = document.getElementById("taskSyncGoogleBtn");
        if (btn) { btn.disabled = true; btn.textContent = "⏳ Синхронизация..."; }
        try {
          const googleEventId = await _pushGoogleEvent(persisted.id, persisted.title, persisted.deadline, _myGoogleEventId(persisted));
          state.taskModal = null;
          state.taskModalSource = "project";
          const live = _findLiveTaskById(persisted.id);
          if (live) live.googleEventIds = { ...(live.googleEventIds || {}), [_adminSession.user.id]: googleEventId };
          save(); render();
          toast("📅 Задача синхронизирована с Google Calendar");
        } catch (e) {
          save(); render();
          toast("Ошибка: " + e.message);
        }
      }

      // Для настоящей карточки задачи (renderTaskCard, мини-канбан внутри сделки) —
      // в отличие от syncTaskModalToGoogle(), тут нет черновика: task уже часть
      // state.tasks с автосохранением полей, коммитить нечего.
      async function syncTaskToGoogle(taskId) {
        const task = (state.tasks || []).find(t => t.id === taskId);
        if (!task) return;
        if (!_googleCalStatus || !_googleCalStatus.connected) { toast("Сначала подключите Google Calendar в Настройках"); return; }
        if (!task.deadline) { toast("Сначала укажите дедлайн задачи"); return; }
        const btn = document.getElementById(`taskSyncGoogleBtn_${taskId}`);
        if (btn) { btn.disabled = true; btn.textContent = "⏳ Синхронизация..."; }
        try {
          const googleEventId = await _pushGoogleEvent(task.id, task.title, task.deadline, _myGoogleEventId(task));
          updateTask(task.id, "googleEventIds", { ...(task.googleEventIds || {}), [_adminSession.user.id]: googleEventId });
          toast("📅 Задача синхронизирована с Google Calendar");
        } catch (e) {
          render();
          toast("Ошибка: " + e.message);
        }
      }

      // Дедлайн сделки (state.project.deadline) — отдельная сущность от задач,
      // своя персональная привязка к Google-событию (googleEventIds, как у задач),
      // дублируется в соответствующую запись state.savedProjects для сохранения
      // между сессиями.
      async function syncProjectDeadlineToGoogle() {
        if (!state.activeProjectId) { toast("Сначала сохраните сделку"); return; }
        if (!_googleCalStatus || !_googleCalStatus.connected) { toast("Сначала подключите Google Calendar в Настройках"); return; }
        if (!state.project.deadline) { toast("Сначала укажите дедлайн"); return; }
        const btn = document.getElementById("projectSyncGoogleBtn");
        if (btn) { btn.disabled = true; btn.textContent = "⏳ Синхронизация..."; }
        try {
          const googleEventId = await _pushGoogleEvent(state.activeProjectId, `Дедлайн: ${state.project.name}`, state.project.deadline, _myGoogleEventId(state.project));
          const nextIds = { ...(state.project.googleEventIds || {}), [_adminSession.user.id]: googleEventId };
          state.project.googleEventIds = nextIds;
          const saved = state.savedProjects.find(p => p.id === state.activeProjectId);
          if (saved) saved.googleEventIds = nextIds;
          save();
          toast("📅 Дедлайн синхронизирован с Google Calendar");
          render();
        } catch (e) {
          render();
          toast("Ошибка: " + e.message);
        }
      }

      async function forceSaveToCloud() {
        if (!_supabase || !_adminSession) { toast("Не подключено к Supabase"); return; }
        const agencyId = getAgencyId();
        const data = Object.fromEntries(Object.entries(state).filter(([k]) => !SYNC_SKIP_KEYS.has(k)));
        const updatedAt = new Date().toISOString();
        try {
          await _supabase.from("agency_state").upsert({ id: agencyId, state_json: data, updated_at: updatedAt });
          _setCloudSyncMark({ agencyId, cloudUpdatedAt: updatedAt, dirty: false });
          _cloudDirty = false;
          toast("☁️ Данные сохранены в облако");
        } catch(e) { toast("Ошибка сохранения: " + e.message); }
      }

      // Отзывает старую ссылку на iCal-фид и выдаёт новую. Смена идёт через RPC,
      // а не UPDATE profiles: колонка calendar_token запинена триггером
      // protect_subscription_fields, иначе пользователь мог бы выставить себе
      // токен чужого агентства и читать его фид.
      async function rotateCalendarToken() {
        if (!_supabase || !_adminSession) { toast("Не подключено к Supabase"); return; }
        const had = !!(_userProfile && _userProfile.calendar_token);
        if (had && !confirm("Старая ссылка перестанет работать сразу. Календарь на телефоне и у коллег придётся переподписать заново. Продолжить?")) return;
        try {
          const { data, error } = await _supabase.rpc("rotate_calendar_token");
          if (error) throw error;
          if (!data) throw new Error("пустой ответ");
          if (_userProfile) _userProfile.calendar_token = data;
          render();
          toast(had ? "🔑 Ссылка на календарь обновлена" : "🔑 Ссылка на календарь создана");
        } catch(e) {
          toast("Не удалось обновить ссылку: " + (e.message || e));
        }
      }

      function openChangePassword() {
        const box = document.getElementById("changePasswordBox");
        if (!box) return;
        box.innerHTML = `
          <div class="panel" style="box-shadow:none;background:var(--panel2);margin-top:18px">
            <h2 style="margin-top:0;font-size:17px">Изменить пароль</h2>
            <div class="grid two">
              <div class="field">
                <label>Новый пароль</label>
                <input type="password" id="newPassInput" placeholder="мин. 6 символов">
              </div>
              <div class="field">
                <label>Повторите пароль</label>
                <input type="password" id="newPassConfirm" placeholder="">
              </div>
            </div>
            <div class="toolbar" style="margin-top:12px">
              <button class="btn primary" onclick="app.submitChangePassword()">Сохранить пароль</button>
              <button class="btn" onclick="document.getElementById('changePasswordBox').innerHTML=''">Отмена</button>
            </div>
          </div>
        `;
      }

      async function submitChangePassword() {
        const p1 = document.getElementById("newPassInput") && document.getElementById("newPassInput").value;
        const p2 = document.getElementById("newPassConfirm") && document.getElementById("newPassConfirm").value;
        if (!p1 || p1.length < 6) { toast("Пароль должен быть не менее 6 символов"); return; }
        if (p1 !== p2) { toast("Пароли не совпадают"); return; }
        if (!_supabase) return;
        const { error } = await _supabase.auth.updateUser({ password: p1 });
        if (error) { toast("Ошибка: " + error.message); return; }
        toast("✅ Пароль успешно изменён");
        document.getElementById("changePasswordBox").innerHTML = "";
      }

      async function confirmDeleteAccount() {
        if (!(await confirmDialog({
          title: "Удалить аккаунт?",
          message: "Аккаунт и все данные профиля будут удалены безвозвратно. Это действие нельзя отменить.",
          okText: "Удалить навсегда", danger: true
        }))) return;
        if (!_supabase) return;
        try {
          const { data: { session } } = await _supabase.auth.getSession();
          if (!session) { toast("Ошибка: нет активной сессии"); return; }
          const { url: sbUrl } = getSupabaseConfig();
          const res = await fetch(`${sbUrl}/functions/v1/delete-account`, {
            method: "POST",
            headers: { Authorization: `Bearer ${session.access_token}`, "Content-Type": "application/json" },
          });
          if (!res.ok) {
            const body = await res.json().catch(() => ({}));
            toast("Ошибка удаления: " + (body.error || res.status)); return;
          }
          lsRemove(STORAGE_KEY);
          lsRemove(LAST_AGENCY_KEY);
          await _supabase.auth.signOut();
          toast("✅ Аккаунт удалён");
        } catch(e) { toast("Ошибка удаления: " + e.message); }
      }

