                  (state.savedProjects || []).forEach(p => {
                    const c = (p.client || "").trim() || "Без клиента";
                    byClient[c] = (byClient[c] || 0) + numberValue(p.paid, 0);
                  });
                  const entries = Object.entries(byClient).filter(([, v]) => v > 0).sort((a, b) => b[1] - a[1]).slice(0, 5);
