      /* ═══════════════════════════════════════════════════════
         РЕДАКТИРОВАНИЕ ТРАНЗАКЦИИ
      ═══════════════════════════════════════════════════════ */
      function openEditTransaction(id, type, projectId) {
        let tx = null;
        if (projectId === state.activeProjectId) {
          tx = (type === "income" ? state.payments : state.expenses).find(t => t.id === id);
        } else {
          const proj = state.savedProjects.find(p => p.id === projectId);
          if (proj && proj.snapshot) {
            const arr = type === "income" ? proj.snapshot.payments : proj.snapshot.expenses;
            tx = (arr || []).find(t => t.id === id);
          }
        }
        if (!tx) { toast("Транзакция не найдена"); return; }
        state.editTransactionModal = { ...tx, _type: type, projectId, editId: id };
        _armDirtyCheck(state.editTransactionModal);
        renderModal();
      }
      async function closeEditTransactionModal() {
        if (!(await _confirmDiscardIfDirty(state.editTransactionModal))) return;
        state.editTransactionModal = null;
        renderModal();
      }
      function saveEditTransaction() {
        const m = state.editTransactionModal;
        if (!m) return;
        const amount = numberValue(m.amount, 0);
        if (amount <= 0) { toast("Введи сумму больше нуля"); return; }

        function updateArr(arr) {
          const idx = arr.findIndex(t => t.id === m.editId);
          if (idx >= 0) arr[idx] = { ...arr[idx], title: m.title, amount, date: m.date, method: m.method || "", category: m.category || "", note: m.note || "" };
        }

        if (m.projectId === state.activeProjectId) {
          if (m._type === "income") updateArr(state.payments);
          else updateArr(state.expenses);
        } else {
          const proj = state.savedProjects.find(p => p.id === m.projectId);
          if (proj && proj.snapshot) {
            if (m._type === "income") { updateArr(proj.snapshot.payments || []); proj.paid = (proj.snapshot.payments || []).reduce((s, p) => s + numberValue(p.amount, 0), 0); }
            else { updateArr(proj.snapshot.expenses || []); proj.expensesTotal = (proj.snapshot.expenses || []).reduce((s, e) => s + numberValue(e.amount, 0), 0); }
          }
        }
        toast("Транзакция обновлена");
        state.editTransactionModal = null;
        save();
        render();
      }
      function deleteEditTransaction() {
        const m = state.editTransactionModal;
        if (!m) return;
        let restore = null;
        if (m.projectId === state.activeProjectId) {
          const arr = m._type === "income" ? state.payments : state.expenses;
          const idx = arr.findIndex(t => t.id === m.editId);
          if (idx >= 0) {
            const removed = arr[idx];
            if (m._type === "income") state.payments = state.payments.filter(t => t.id !== m.editId);
            else state.expenses = state.expenses.filter(t => t.id !== m.editId);
            restore = () => {
              (m._type === "income" ? state.payments : state.expenses).splice(idx, 0, removed);
            };
          }
        } else {
          const proj = state.savedProjects.find(p => p.id === m.projectId);
          if (proj && proj.snapshot) {
            const key = m._type === "income" ? "payments" : "expenses";
            const idx = (proj.snapshot[key] || []).findIndex(t => t.id === m.editId);
            const recalc = () => {
              if (m._type === "income") proj.paid = (proj.snapshot.payments || []).reduce((s, p) => s + numberValue(p.amount, 0), 0);
              else proj.expensesTotal = (proj.snapshot.expenses || []).reduce((s, e) => s + numberValue(e.amount, 0), 0);
            };
            if (idx >= 0) {
              const removed = proj.snapshot[key][idx];
              proj.snapshot[key] = proj.snapshot[key].filter(t => t.id !== m.editId);
              recalc();
              restore = () => {
                proj.snapshot[key].splice(idx, 0, removed);
                recalc();
              };
            }
          }
        }
        state.editTransactionModal = null;
        save();
        render();
        if (restore) {
          toastUndo("Транзакция удалена", () => {
            restore();
            save(); render();
            toast("Удаление отменено");
          });
        }
      }
      function setEditTransactionField(key, value) {
        if (!state.editTransactionModal) return;
        state.editTransactionModal[key] = value;
        // renderModal() здесь БЫЛ и ломал ввод: он переписывает innerHTML модалки
        // целиком, поле пересоздаётся, фокус улетает в body (переносить его обратно
        // _enhanceModalA11y умышленно не умеет — только при открытии). На практике это
        // значило, что в сумму поступления удавалось ввести ровно один символ, дальше
        // нажатия уходили в никуда. Замер: «123» в поле 20750 давало «207501».
        // Ничего в этой модалке от повторного рендера не зависит — значения полей
        // читает saveEditTransaction() из состояния. Ср. setFinanceModalField.
      }
      function renderEditTransactionModal() {
        const m = state.editTransactionModal;
        if (!m) return "";
        const isIncome = m._type === "income";
        const amount = numberValue(m.amount, 0);
        return `
          <div class="modal-overlay" onclick="event.target===this&&app.closeEditTransactionModal()">
            <div class="modal-box">
              <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:18px">
                <h2 class="u-title-20">Редактировать ${isIncome ? "поступление" : "расход"}</h2>
                <button onclick="app.closeEditTransactionModal()" class="u-modal-close" aria-label="Закрыть">×</button>
              </div>
              <div class="field" style="margin-bottom:14px">
                <label style="font-size:12px;color:var(--muted);font-weight:700;letter-spacing:.04em">СУММА, ₽ *</label>
                <input class="modal-amount-input" type="text" inputmode="numeric" autocomplete="off"
                  value="${escapeHtml(groupDigits(m.amount))}"
                  oninput="app.setEditTransactionField('amount',app.formatAmountField(this))">
              </div>
              <div class="grid two" style="margin-bottom:14px">
                <div class="field">
                  <label>Описание</label>
                  <input value="${escapeHtml(m.title || "")}" oninput="app.setEditTransactionField('title',this.value)">
                </div>
                <div class="field">
                  <label>Дата</label>
                  <input type="date" value="${escapeHtml(m.date || "")}" onchange="app.setEditTransactionField('date',this.value)">
                </div>
              </div>
              <div class="field" style="margin-bottom:14px">
                <label>${isIncome ? "Статья" : "Категория"}</label>
                <select onchange="app.setEditTransactionField('category',this.value)">
                  ${isIncome
                    ? PAYMENT_ARTICLES.map(c => `<option value="${c}" ${m.category === c ? "selected" : ""}>${c}</option>`).join("")
                    : EXPENSE_CATEGORIES.map(c => `<option value="${c}" ${m.category === c ? "selected" : ""}>${c}</option>`).join("")
                  }
                </select>
              </div>
              <div class="field" style="margin-bottom:22px">
                <label>Комментарий</label>
                <textarea style="min-height:64px" oninput="app.setEditTransactionField('note',this.value)" placeholder="Необязательно">${escapeHtml(m.note || "")}</textarea>
              </div>
              <div style="display:flex;justify-content:space-between;align-items:center;gap:10px">
                <button class="btn danger small" onclick="app.deleteEditTransaction()">${TRASH_SVG} Удалить</button>
                <div class="u-flex-g8">
                  <button class="btn" onclick="app.closeEditTransactionModal()">Отмена</button>
                  <button class="modal-save-btn ${isIncome ? "income" : "expense"}" onclick="app.saveEditTransaction()">Сохранить</button>
                </div>
              </div>
            </div>
          </div>
        `;
      }

      /* ═══════════════════════════════════════════════════════
         КЛИЕНТ MODAL
      ═══════════════════════════════════════════════════════ */
      function openClientModal(clientId) {
        if (!clientId) {
          state.clientModal = { id: "", name: "", company: "", phone: "", email: "", city: "", status: "new", note: "" };
          _armDirtyCheck(state.clientModal);
          renderModal();
          return;
        }
        const client = (state.clients || []).find(c => c.id === clientId);
        if (!client) return;
        state.clientModal = { ...client };
        _armDirtyCheck(state.clientModal);
        renderModal();
      }
      async function closeClientModal() {
        if (!(await _confirmDiscardIfDirty(state.clientModal))) return;
        state.clientModal = null;
        renderModal();
      }
      function setClientModalField(key, value) {
        if (!state.clientModal) return;
        state.clientModal[key] = value;
      }
      async function saveClientModal() {
        const m = state.clientModal;
        if (!m) return;
        if (m.phone && !validatePhone(m.phone)) {
          toast("❌ Неверный формат телефона. Пример: +7 900 000-00-00");
          return;
        }
        if (!m.id) {
          // Detect duplicates by phone or email before creating
          const phone = (m.phone || "").replace(/\D/g, "");
          const email = (m.email || "").trim().toLowerCase();
          const dup = (state.clients || []).find(c => {
            if (phone && c.phone && c.phone.replace(/\D/g, "") === phone) return true;
            if (email && c.email && c.email.trim().toLowerCase() === email) return true;
            return false;
          });
          if (dup) {
            const field = phone && dup.phone?.replace(/\D/g,"") === phone ? "телефоном" : "email";
            if (!(await confirmDialog({
              title: "Возможный дубль",
              message: `Клиент «${dup.name}» с таким же ${field} уже существует. Всё равно создать нового?`,
              okText: "Создать"
            }))) return;
          }
          const created = normalizeClient({ ...m, name: String(m.name || "").trim() || "Новый клиент" });
          state.clients = [created, ...(state.clients || [])];
          state.clientModal = null;
          toast("Клиент добавлен");
          save();
          render();
          return;
        }
        const idx = (state.clients || []).findIndex(c => c.id === m.id);
        if (idx >= 0) {
          state.clients[idx] = normalizeClient({ ...state.clients[idx], ...m, updatedAt: new Date().toISOString() });
          // Синхронизируем имя клиента во всех связанных сделках — включая архивный
          // снапшот и текущую открытую смету, а не только верхнеуровневое поле карточки
          (state.savedProjects || []).forEach(p => {
            if (p.clientId !== m.id) return;
            p.client = m.name || p.client;
            if (p.snapshot && p.snapshot.project) {
              p.snapshot.project.client = p.client;
              p.snapshot.project.clientId = m.id;
            }
            if (p.id === state.activeProjectId) {
              state.project.client = p.client;
              state.project.clientId = m.id;
            }
          });
        }
        // Сохраняем дедлайн проекта если открыто из карточки сделки
        if (m._projectId) {
          const proj = (state.savedProjects || []).find(p => p.id === m._projectId);
          if (proj) {
            proj.deadline = m._projectDeadline || "";
            if (proj.snapshot && proj.snapshot.project) proj.snapshot.project.deadline = proj.deadline;
          }
        }
        state.clientModal = null;
        toast("Сохранено");
        save();
        render();
      }
      function renderClientModalHtml() {
        const m = state.clientModal;
        if (!m) return "";
        return `
          <div class="modal-overlay" onclick="event.target===this&&app.closeClientModal()">
            <div class="modal-box" style="width:min(560px,calc(100vw - 32px))">
              <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:18px">
                <h2 class="u-title-20">${m.id ? "Редактировать клиента" : "Новый клиент"}</h2>
                <button onclick="app.closeClientModal()" class="u-modal-close" aria-label="Закрыть">×</button>
              </div>
              <div class="grid two" style="margin-bottom:12px">
                ${field("Имя / название *", `<input value="${escapeHtml(m.name || "")}" oninput="app.setClientModalField('name',this.value)" placeholder="Имя клиента">`)}
                ${field("Компания", `<input value="${escapeHtml(m.company || "")}" oninput="app.setClientModalField('company',this.value)">`)}
                ${field("Телефон", `<input value="${escapeHtml(m.phone || "")}" onfocus="app.maskPhoneFocus(this)" oninput="app.maskPhoneInput(this);app.setClientModalField('phone',this.value)" onblur="app.checkPhoneField(this)" placeholder="+7 900 000-00-00">`)}
                ${field("Email", `<input value="${escapeHtml(m.email || "")}" oninput="app.setClientModalField('email',this.value)" placeholder="mail@...">`)}
                ${field("Город", `<input value="${escapeHtml(m.city || "")}" oninput="app.setClientModalField('city',this.value)">`)}
                ${field("Статус", `<select onchange="app.setClientModalField('status',this.value)">
                  ${["new","active","vip","paused","lost"].map(s => `<option value="${s}" ${m.status === s ? "selected" : ""}>${{new:"Новый",active:"Активный",vip:"VIP",paused:"Пауза",lost:"Потерян"}[s]}</option>`).join("")}
                </select>`)}
              </div>
              ${m._projectId ? `
              <div style="background:rgba(124,58,237,.06);border:1px solid rgba(124,58,237,.2);border-radius:12px;padding:14px 16px;margin-bottom:14px">
                <div style="font-size:12px;font-weight:800;color:var(--primary2);margin-bottom:10px">📅 Дедлайн проекта</div>
                <input type="date" value="${escapeHtml(m._projectDeadline||"")}"
                  oninput="app.setClientModalField('_projectDeadline',this.value)"
                  style="width:100%;border-radius:10px;border:1px solid var(--line);background:var(--input);color:var(--text);padding:10px 12px;font-size:14px">
              </div>` : ""}
              <div class="field" style="margin-bottom:14px">
                ${field("Заметка", `<textarea style="min-height:72px" oninput="app.setClientModalField('note',this.value)" placeholder="Предпочтения, условия...">${escapeHtml(m.note || "")}</textarea>`)}
              </div>
              <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap">
                <div class="u-flex-g8">
                  ${m.id ? `<button class="btn small" onclick="app.closeClientModal();app.openClientDetail('${m.id}')">Проекты →</button>` : ""}
                  ${m.id ? `<button class="btn danger small" onclick="app.closeClientModal();app.deleteClient('${m.id}')">${TRASH_SVG} Удалить клиента</button>` : ""}
                </div>
                <div class="u-flex-g8">
                  <button class="btn" onclick="app.closeClientModal()">Отмена</button>
                  <button class="btn primary" onclick="app.saveClientModal()">${m.id ? "Сохранить" : "Добавить"}</button>
                </div>
              </div>
            </div>
          </div>
        `;
      }

      /* ═══════════════════════════════════════════════════════
         СДЕЛКА MODAL (редактировать сделку из карточки)
      ═══════════════════════════════════════════════════════ */
      let _dealSwitcherQuery = "";
      // «Завершённые» обычно самая длинная группа (сотни сделок) и перекрывает собой
      // «В работе»/«Архив» при скролле — по умолчанию свёрнута, остальные две открыты.
      let _dealSwitcherCollapsed = { active: false, completed: true, archived: false };
      function toggleDealSwitcherSection(key) {
        _dealSwitcherCollapsed[key] = !_dealSwitcherCollapsed[key];
        const list = document.getElementById("dealSwitcherList");
        if (list) list.innerHTML = renderDealSwitcherListHtml();
      }
      function toggleDealSwitcher(e) {
        e && e.stopPropagation();
        state.dealSwitcherOpen = !state.dealSwitcherOpen;
        if (state.dealSwitcherOpen) {
          _dealSwitcherQuery = "";
          renderDealBar();
          setTimeout(() => document.getElementById("dealSwitcherSearch")?.focus(), 60);
        } else {
          renderDealBar();
        }
      }
      function closeDealSwitcher() {
        state.dealSwitcherOpen = false;
        renderDealBar();
      }
      function filterDealSwitcher(value) {
        _dealSwitcherQuery = value;
        const list = document.getElementById("dealSwitcherList");
        if (list) list.innerHTML = renderDealSwitcherListHtml();
      }
      function switchDeal(projectId) {
        state.dealSwitcherOpen = false;
        renderDealBar();
        openDeal(projectId);
      }
      function renderDealBar() {
        const btnEl = document.getElementById("dealBarSwitcher");
        if (btnEl) btnEl.innerHTML = renderDealSwitcherButtonHtml();
        const overlayEl = document.getElementById("dealSwitcherOverlay");
        if (overlayEl) overlayEl.innerHTML = renderDealSwitcherOverlayHtml();
      }
      function _dealSwitcherFilteredProjects() {
        const projects = (state.savedProjects || []).slice();
        const q = _dealSwitcherQuery.trim().toLowerCase();
        return q
          ? projects.filter(p => (p.name || "").toLowerCase().includes(q) || (p.client || "").toLowerCase().includes(q))
          : projects;
      }
      function _dealSwitcherItemHtml(p, extraClass) {
        const cur = state.activeProjectId;
        const isActive = p.id === cur;
        const u = p.deadline ? deadlineUrgency(p.deadline) : null;
        return `
          <div class="deal-switcher-item ${isActive ? "active" : ""} ${extraClass || ""}" onclick="app.switchDeal('${p.id.replace(/'/g, "")}')">
            <div class="deal-switcher-item-name">${escapeHtml(p.name || "Без названия")}</div>
            <div class="deal-switcher-item-sub">
              ${p.client ? `<span>${escapeHtml(p.client)}</span>` : ""}
              <span class="status-pill" style="font-size:12px;padding:1px 7px">${escapeHtml(p.crmStatus || "Лид")}</span>
              ${p.deadline ? `<span style="color:${u && u.level !== "ok" ? u.color : "var(--muted)"}">📅 ${escapeHtml(formatDate(p.deadline))}</span>` : ""}
            </div>
          </div>
        `;
      }
      function renderDealSwitcherListHtml() {
        const projects = _dealSwitcherFilteredProjects();
        if (!projects.length) {
          return `<div class="deal-switcher-panel-empty">Ничего не найдено</div>`;
        }
        const crmOrder = idx => { const i = CRM_STATUSES.indexOf(idx); return i < 0 ? 99 : i; };
        const active = projects
          .filter(p => (p.crmStatus || "Лид") !== "Завершённые" && (p.crmStatus || "Лид") !== CRM_ARCHIVED)
          .sort((a, b) => {
            const d = crmOrder(a.crmStatus || "Лид") - crmOrder(b.crmStatus || "Лид");
            return d !== 0 ? d : (b.updatedAt || "").localeCompare(a.updatedAt || "");
          });
        const completed = projects
          .filter(p => (p.crmStatus || "Лид") === "Завершённые")
          .sort((a, b) => (b.updatedAt || "").localeCompare(a.updatedAt || ""));
        const archived = projects
          .filter(p => (p.crmStatus || "Лид") === CRM_ARCHIVED)
          .sort((a, b) => (b.updatedAt || "").localeCompare(a.updatedAt || ""));
        const section = (key, label, cls, items, itemCls, extraStyle) => {
          if (!items.length) return "";
          const collapsed = !!_dealSwitcherCollapsed[key];
          return `
            <button type="button" class="deal-switcher-section-label ${cls}" style="${extraStyle||""}" onclick="app.toggleDealSwitcherSection('${key}')">
              <span>${label} (${items.length})</span>
              <span class="deal-switcher-section-chevron ${collapsed ? "" : "open"}">▾</span>
            </button>
            ${collapsed ? "" : items.map(p => _dealSwitcherItemHtml(p, itemCls)).join("")}
          `;
        };
        return `
          ${section("active", "В работе", "active-label", active, "active-deal")}
          ${section("completed", "Завершённые", "completed-label", completed, "completed-deal", "margin-top:8px")}
          ${section("archived", "Архив", "archived-label", archived, "archived-deal", "margin-top:8px")}
        `;
      }
      function renderDealSwitcherButtonHtml() {
        const projects = (state.savedProjects || []);
        const cur = state.activeProjectId;
        const curProj = projects.find(p => p.id === cur);
        return `
          <div class="deal-switcher">
            <button class="deal-switcher-btn" onclick="app.toggleDealSwitcher(event)" title="Переключить сделку">
              <span class="deal-switcher-btn-label">${escapeHtml((curProj && curProj.name) || state.project.name || "Без названия")}</span>
              <span class="deal-switcher-chevron ${state.dealSwitcherOpen ? "open" : ""}">▼</span>
            </button>
          </div>
        `;
      }
      function renderDealSwitcherOverlayHtml() {
        if (!state.dealSwitcherOpen) return "";
        const sidebarEl = document.getElementById("appSidebar");
        const panelLeft = sidebarEl ? sidebarEl.offsetWidth : 0;
        return `
          <div class="deal-switcher-backdrop" onclick="app.closeDealSwitcher()"></div>
          <div class="deal-switcher-panel" style="left:${panelLeft}px" onclick="event.stopPropagation()">
            <div class="deal-switcher-panel-header">
              <h3>Все сделки</h3>
              <button class="deal-switcher-panel-close" onclick="app.closeDealSwitcher()" aria-label="Закрыть">&times;</button>
            </div>
            <div class="deal-switcher-search-wrap">
              <input id="dealSwitcherSearch" class="deal-switcher-search" type="text" placeholder="Поиск по названию или клиенту…" value="${escapeHtml(_dealSwitcherQuery)}" oninput="app.filterDealSwitcher(this.value)">
            </div>
            <div class="deal-switcher-panel-list" id="dealSwitcherList">${renderDealSwitcherListHtml()}</div>
          </div>
        `;
      }

      function openDealModal(projectId) {
        const project = (state.savedProjects || []).find(p => p.id === projectId);
        if (!project) return;
        state.dealModal = {
          id: project.id,
          name: project.name || "",
          client: project.client || "",
          clientId: project.clientId || "",
          crmStatus: project.crmStatus || "Лид",
          deadline: project.deadline || "",
          manager: project.manager || "",
          tags: project.tags ? [...project.tags] : [],
          total: project.total || 0,
          // Смета разбита на позиции? Если да — сумма считается по ним, поле «Бюджет»
          // не показываем (оно бы конфликтовало с расчётом). Если нет (импорт из
          // O!task пришёл суммой или пустым) — даём вписать бюджет вручную.
          hasSmetaLines: Object.keys((project.snapshot || {}).selected || {}).length > 0
        };
        _armDirtyCheck(state.dealModal);
        renderModal();
      }
      async function closeDealModal() {
        if (!(await _confirmDiscardIfDirty(state.dealModal))) return;
        state.dealModal = null;
        renderModal();
      }
      function setDealModalField(key, value) {
        if (!state.dealModal) return;
        state.dealModal[key] = value;
      }
      function linkDealClient(projectId, clientId) {
        const proj = (state.savedProjects || []).find(p => p.id === projectId);
        if (!proj) return;
        const client = clientId ? (state.clients || []).find(c => c.id === clientId) : null;
        proj.clientId = client ? client.id : "";
        proj.client = client ? client.name : proj.client;
        if (proj.snapshot && proj.snapshot.project) {
          proj.snapshot.project.clientId = proj.clientId;
          proj.snapshot.project.client = proj.client;
        }
        if (proj.id === state.activeProjectId) {
          state.project.clientId = proj.clientId;
          state.project.client = proj.client;
        }
        if (state.dealModal && state.dealModal.id === projectId) {
          state.dealModal.clientId = proj.clientId;
          state.dealModal.client = proj.client;
        }
        toast(client ? `Сделка привязана к клиенту «${client.name}»` : "Сделка отвязана от клиента");
        save();
        renderModal();
        render();
      }
      function _addDealTag(val) {
        if (!state.dealModal) return;
        const tag = (val || "").trim().toLowerCase();
        if (!tag) return;
        state.dealModal.tags = state.dealModal.tags || [];
        if (!state.dealModal.tags.includes(tag)) state.dealModal.tags.push(tag);
        renderModal();
      }
      function _removeDealTag(tag) {
        if (!state.dealModal) return;
        state.dealModal.tags = (state.dealModal.tags || []).filter(t => t !== tag);
        renderModal();
      }
      function setCrmTagFilter(tag) {
        state.crmTagFilter = state.crmTagFilter === tag ? "" : tag;
        render();
      }
      function saveDealModal() {
        const m = state.dealModal;
        if (!m) return;
        const proj = (state.savedProjects || []).find(p => p.id === m.id);
        if (proj) {
          proj.name = m.name || proj.name;
          proj.crmStatus = m.crmStatus || proj.crmStatus;
          proj.deadline = m.deadline || "";
          proj.manager = m.manager || "";
          proj.tags = m.tags || [];
          // Бюджет вручную — только для сделок без разбитой сметы (импорт/пустая смета).
          // Держим финансы согласованными: долг = бюджет − оплата, выручка = бюджет,
          // прибыль = бюджет − расходы. _totalForSave потом бережёт это при открытии.
          if (!m.hasSmetaLines) {
            const budget = numberValue(m.total, 0);
            proj.total = budget;
            proj.debt = Math.max(0, budget - numberValue(proj.paid, 0));
            proj.revenue = budget;
            proj.profit = budget - numberValue(proj.expensesTotal, 0);
            if (proj.snapshot) proj.snapshot.total = budget;
          }
          if (proj.snapshot && proj.snapshot.project) {
            proj.snapshot.project.deadline = proj.deadline;
            proj.snapshot.project.crmStatus = proj.crmStatus;
            proj.snapshot.project.name = proj.name;
            proj.snapshot.project.manager = proj.manager;
          }
          if (proj.id === state.activeProjectId) {
            state.project.name = proj.name;
            state.project.crmStatus = proj.crmStatus;
            state.project.deadline = proj.deadline;
            state.project.manager = proj.manager;
          }
        }
        state.dealModal = null;
        toast("Сделка сохранена");
        save();
        render();
      }
      function renderDealModalHtml() {
        const m = state.dealModal;
        if (!m) return "";
        const u = m.deadline ? deadlineUrgency(m.deadline) : null;
        return `
          <div class="modal-overlay" onclick="event.target===this&&app.closeDealModal()">
            <div class="modal-box" style="width:min(560px,calc(100vw - 32px))">
              <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:18px;flex-wrap:wrap;gap:8px">
                <h2 class="u-title-20">Редактировать сделку</h2>
                <div style="display:flex;align-items:center;gap:8px">
                  <button class="btn small" onclick="app.quickContractFromDeal('${escapeHtml(m.id)}')" title="Создать договор с данными этой сделки">📄 Договор</button>
                  <button onclick="app.closeDealModal()" class="u-modal-close" aria-label="Закрыть">×</button>
                </div>
              </div>
              <div class="grid two" style="margin-bottom:12px">
                ${field("Название сделки *", `<input value="${escapeHtml(m.name || "")}" oninput="app.setDealModalField('name',this.value)" placeholder="Название проекта">`)}
                ${field("Клиент", `
                  <select onchange="app.linkDealClient('${escapeHtml(m.id)}', this.value)" title="Привяжи к клиенту из справочника — тогда переименование клиента подтянется сюда автоматически">
                    ${!m.clientId && m.client ? `<option value="" selected>${escapeHtml(m.client)} (не привязан)</option>` : `<option value="">— не привязан —</option>`}
                    ${(state.clients || []).map(c => optionValueHtml(c.id, c.company ? `${c.name} · ${c.company}` : c.name, m.clientId)).join("")}
                  </select>
                `)}
                ${field("Статус воронки", `<select onchange="app.setDealModalField('crmStatus',this.value)">
                  ${CRM_STATUSES.map(s => `<option value="${s}" ${m.crmStatus === s ? "selected" : ""}>${s}</option>`).join("")}
                  <option value="${CRM_ARCHIVED}" ${m.crmStatus === CRM_ARCHIVED ? "selected" : ""}>${CRM_ARCHIVED}</option>
                </select>`)}
                ${field("Менеджер", `<input value="${escapeHtml(m.manager || "")}" oninput="app.setDealModalField('manager',this.value)" placeholder="Имя менеджера">`)}
              </div>
              <div style="background:rgba(124,58,237,.06);border:1px solid rgba(124,58,237,.2);border-radius:12px;padding:14px 16px;margin-bottom:14px">
                <div style="font-size:12px;font-weight:800;color:var(--primary2);margin-bottom:10px">📅 Дедлайн проекта${u && u.level !== "ok" ? ` <span style="color:${u.color};font-weight:700">· ${escapeHtml(u.label)}</span>` : ""}</div>
                <input type="date" value="${escapeHtml(m.deadline||"")}"
                  oninput="app.setDealModalField('deadline',this.value)"
                  style="width:100%;border-radius:10px;border:1px solid var(--line);background:var(--input);color:var(--text);padding:10px 12px;font-size:14px">
              </div>
              ${!m.hasSmetaLines ? `
              <div class="field" style="margin-bottom:14px">
                ${field("Бюджет сделки, ₽", `<input type="text" inputmode="numeric" value="${m.total ? Number(m.total).toLocaleString("ru-RU") : ""}" oninput="app.setDealModalField('total', app.maskMoneyInput(this))" placeholder="Например, 241 938">`)}
                <p class="mini-note" style="margin-top:6px">Смета не разбита на позиции — укажите общую сумму. Разбейте её на позиции в смете, если нужны КП и расчёт маржи.</p>
              </div>
              ` : ""}
              <div class="field" style="margin-bottom:14px">
                <label style="font-size:12px;color:var(--muted);font-weight:750;margin-bottom:6px;display:block">Теги</label>
                <div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px">
                  ${(m.tags||[]).map(t => `<span style="display:inline-flex;align-items:center;gap:4px;background:rgba(124,58,237,.12);border:1px solid rgba(124,58,237,.3);border-radius:99px;padding:3px 10px;font-size:12px;font-weight:600;color:var(--primary2)">${escapeHtml(t)}<button onclick="app._removeDealTag('${escapeHtml(t)}')" style="background:none;border:none;cursor:pointer;color:var(--muted);padding:0;line-height:1;font-size:14px">×</button></span>`).join("")}
                </div>
                <div style="display:flex;gap:6px">
                  <input id="dealTagInput" placeholder="Новый тег..." style="flex:1;padding:7px 11px;border:1px solid var(--line);border-radius:8px;background:var(--input);color:var(--text);font-size:13px"
                    onkeydown="if(event.key==='Enter'){event.preventDefault();app._addDealTag(this.value);this.value=''}">
                  <button class="btn small" onclick="app._addDealTag(document.getElementById('dealTagInput').value);document.getElementById('dealTagInput').value=''">+ Тег</button>
                </div>
              </div>
              <div style="display:flex;justify-content:flex-end;gap:8px">
                <button class="btn" onclick="app.closeDealModal()">Отмена</button>
                <button class="btn primary" onclick="app.saveDealModal()">Сохранить</button>
              </div>
              <div style="margin-top:14px;padding-top:12px;border-top:1px solid var(--line);text-align:center">
                <button onclick="app.deleteDealFromModal('${escapeHtml(m.id)}')" style="background:none;border:none;color:var(--muted);font-size:12px;cursor:pointer;text-decoration:underline;opacity:.6;padding:4px 8px" title="Удалить сделку навсегда">Удалить сделку</button>
              </div>
            </div>
          </div>
        `;
      }

      /* ═══════════════════════════════════════════════════════
         ЗАДАЧА MODAL (открыть задачу из Календаря)
      ═══════════════════════════════════════════════════════ */
      // Модалка задачи обслуживает и проектные задачи (state.tasks, открыта из
      // календаря/канбана), и свободные (state.globalTasks, раздел «Задачи»).
      // taskModalSource говорит, в какую коллекцию писать при сохранении.
      function _taskModalList() {
        return state.taskModalSource === "global"
          ? (Array.isArray(state.globalTasks) ? state.globalTasks : (state.globalTasks = []))
          : state.tasks;
      }
      // Живая задача по id в любой из коллекций (для Google-writeback).
      function _findLiveTaskById(id) {
        return (state.tasks || []).find(t => t.id === id) || (state.globalTasks || []).find(t => t.id === id) || null;
      }

      function openTaskModal(taskId) {
        const task = (state.tasks || []).find(t => t.id === taskId);
        if (!task) { toast("Задача не найдена"); return; }
        state.taskModalSource = "project";
        state.taskModal = { ...task };
        _armDirtyCheck(state.taskModal);
        renderModal();
      }
      async function closeTaskModal() {
        if (!(await _confirmDiscardIfDirty(state.taskModal))) return;
        state.taskModal = null;
        state.taskModalSource = "project";
        renderModal();
      }
      function setTaskModalField(key, value) {
        if (!state.taskModal) return;
        state.taskModal[key] = value;
        renderModal();
      }
      // Переносит черновик state.taskModal в нужную коллекцию (без save()/render()/
      // закрытия модалки) — общая часть для saveTaskModal() и syncTaskModalToGoogle(),
      // которому нужно закоммитить свежие поля перед отправкой в Google, не закрывая
      // модалку если синхронизация упадёт с ошибкой.
      function _commitTaskModal() {
        const m = state.taskModal;
        if (!m) return null;
        const list = _taskModalList();
        const idx = list.findIndex(t => t.id === m.id);
        if (idx < 0) return null;
        const wasDone = list[idx].status === "Готово";
        list[idx] = normalizeTask({ ...list[idx], ...m, updatedAt: new Date().toISOString() });
        if (!wasDone && list[idx].status === "Готово") _maybeRepeatTask(list[idx], list);
        return list[idx];
      }

      function saveTaskModal() {
        const persisted = _commitTaskModal();
        if (persisted) toast("Задача обновлена");
        state.taskModal = null;
        save();
        render();
        if (persisted && persisted.deadline) _autoSyncTaskToGoogle(persisted);
      }

      function addTaskComment() {
        if (!state.taskModal) return;
        const input = document.getElementById("taskCommentDraft");
        const text = (input ? input.value : "").trim();
        if (!text) return;
        const author = getUserSettings().displayName || "Я";
        const comment = { id: uid("cmt"), text, author, createdAt: new Date().toISOString() };
        const list = _taskModalList();
        const idx = list.findIndex(t => t.id === state.taskModal.id);
        if (idx >= 0) {
          if (!Array.isArray(list[idx].comments)) list[idx].comments = [];
          list[idx].comments.push(comment);
          state.taskModal.comments = [...list[idx].comments];
          save();
        }
        renderModal();
      }

      function deleteTaskComment(commentId) {
        if (!state.taskModal) return;
        const list = _taskModalList();
        const idx = list.findIndex(t => t.id === state.taskModal.id);
        if (idx >= 0) {
          list[idx].comments = (list[idx].comments || []).filter(c => c.id !== commentId);
          state.taskModal.comments = [...list[idx].comments];
          save();
        }
        renderModal();
      }
      function renderTaskModalHtml() {
        const m = state.taskModal;
        if (!m) return "";
        return `
          <!-- ВАЖНО: класс modal-overlay обязателен — по нему _enhanceModalA11y() находит
               модалку и выдаёт role=dialog/aria-modal, перенос фокуса внутрь, ловушку Tab
               и возврат фокуса при закрытии. Пока здесь был только task-modal-overlay,
               модалка задачи (самая частая в работе) не получала НИЧЕГО из этого.
               Правила .modal-overlay и .task-modal-overlay в style.css идентичны, так что
               второй класс ничего не меняет визуально. -->
          <div class="modal-overlay task-modal-overlay" onclick="event.target===this&&app.closeTaskModal()">
            <div class="task-modal-box">
              <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px">
                <h2 style="margin:0;font-size:18px">Задача</h2>
                <button onclick="app.closeTaskModal()" class="u-modal-close" aria-label="Закрыть">×</button>
              </div>
              <div class="field" style="margin-bottom:12px">
                ${field("Название", `<input value="${escapeHtml(m.title || "")}" oninput="app.setTaskModalField('title',this.value)">`)}
              </div>
              <div class="grid two" style="margin-bottom:12px">
                ${field("Статус", `<select onchange="app.setTaskModalField('status',this.value)">
                  ${TASK_STATUSES.map(s => `<option value="${s}" ${m.status===s?"selected":""}>${s}</option>`).join("")}
                </select>`)}
                ${field("Приоритет", `<select onchange="app.setTaskModalField('priority',this.value)">
                  ${PRIORITIES.map(s => `<option value="${s}" ${m.priority===s?"selected":""}>${s}</option>`).join("")}
                </select>`)}
                ${field("Дедлайн", `<input type="date" value="${escapeHtml(m.deadline||"")}" onchange="app.setTaskModalField('deadline',this.value)">`)}
                ${field("Ответственный", `<input value="${escapeHtml(m.assignee||"")}" oninput="app.setTaskModalField('assignee',this.value)" placeholder="Имя...">`)}
              </div>
              <div class="field" style="margin-bottom:12px">
                ${field("Повтор", `<select onchange="app.setTaskModalField('repeat',this.value)" title="При переводе в «Готово» создаётся следующая копия со сдвинутым дедлайном">
                  ${TASK_REPEAT_OPTIONS.map(r => `<option value="${r}" ${(m.repeat||"none")===r?"selected":""}>${TASK_REPEAT_LABELS[r]}</option>`).join("")}
                </select>`)}
              </div>
              <div class="field" style="margin-bottom:18px">
                ${field("Заметка", `<textarea style="min-height:80px" oninput="app.setTaskModalField('note',this.value)" placeholder="Детали задачи...">${escapeHtml(m.note||"")}</textarea>`)}
              </div>

              <div style="border-top:1px solid var(--line);padding-top:16px;margin-bottom:18px">
                <div style="font-size:12px;font-weight:750;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;margin-bottom:12px">
                  Комментарии${(m.comments||[]).length ? ` (${m.comments.length})` : ""}
                </div>
                ${(m.comments||[]).length ? `
                  <div style="display:flex;flex-direction:column;gap:8px;margin-bottom:12px">
                    ${(m.comments||[]).map(c => `
                      <div style="background:var(--panel2);border:1px solid var(--line);border-radius:10px;padding:10px 12px;position:relative">
                        <div style="font-size:13px;color:var(--text);line-height:1.5;white-space:pre-wrap;word-break:break-word">${escapeHtml(c.text)}</div>
                        <div style="display:flex;justify-content:space-between;align-items:center;margin-top:6px">
                          <span class="u-meta">${escapeHtml(c.author || "Я")} · ${new Date(c.createdAt).toLocaleString("ru-RU",{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"})}</span>
                          <button onclick="app.deleteTaskComment('${c.id}')" style="background:none;border:none;color:var(--muted);cursor:pointer;font-size:14px;padding:0 2px;line-height:1" title="Удалить комментарий">×</button>
                        </div>
                      </div>
                    `).join("")}
                  </div>
                ` : `<p style="font-size:13px;color:var(--muted);margin:0 0 12px">Комментариев пока нет.</p>`}
                <div style="display:flex;gap:8px;align-items:flex-end">
                  <textarea id="taskCommentDraft" placeholder="Написать комментарий... (Ctrl+Enter — отправить)"
                    onkeydown="if(event.ctrlKey&&event.key==='Enter'){event.preventDefault();app.addTaskComment()}"
                    style="flex:1;min-height:60px;padding:8px 12px;border-radius:10px;border:1px solid var(--line);background:var(--panel2);color:var(--text);font-size:13px;resize:none;font-family:inherit"></textarea>
                  <button class="btn primary" onclick="app.addTaskComment()" style="white-space:nowrap;align-self:flex-end">Добавить</button>
                </div>
              </div>

              <div style="display:flex;justify-content:flex-end;gap:8px">
                <button class="btn" onclick="app.closeTaskModal()">Отмена</button>
                ${_googleCalStatus && _googleCalStatus.connected ? `<button id="taskSyncGoogleBtn" class="btn" onclick="app.syncTaskModalToGoogle()">${_myGoogleEventId(m) ? "🔄 Обновить в Google Calendar" : "📅 В Google Calendar"}</button>` : ""}
                <button class="btn primary" onclick="app.saveTaskModal()">Сохранить</button>
              </div>
            </div>
          </div>
        `;
      }

      /* ═══════════════════════════════════════════════════════
         ОТКРЫТЬ СДЕЛКУ НА ВКЛАДКЕ ЗАДАЧИ
      ═══════════════════════════════════════════════════════ */
      function openDealTasks(projectId) {
        const saved = state.savedProjects.find(p => p.id === projectId);
        if (!saved) return;
        loadSavedProject(projectId);
        state.dealView = "tasks";
        save();
        render();
      }

