      function normalizeContract(c) {
        return {
          id: c?.id || uid("contract"),
          name: c?.name || "Новый договор",
          desc: c?.desc || "",
          category: c?.category || "Прочее",
          body: c?.body || "",
          createdAt: c?.createdAt || new Date().toISOString(),
          updatedAt: c?.updatedAt || new Date().toISOString()
        };
      }

      function createContractFromTemplate(tplId) {
        const tpl = CONTRACT_TEMPLATES.find(t => t.id === tplId);
        const base = tpl || CONTRACT_TEMPLATES[0];
        const contract = normalizeContract({
          name: (base.name || "Договор") + " — " + (state.project.client || state.company.name || "Новый"),
          desc: base.desc || "",
          category: base.category || "Прочее",
          body: (base.body || "").replace("[ИСПОЛНИТЕЛЬ]", state.company.name || "Исполнитель").replace("[ЗАКАЗЧИК]", state.project.client || "Заказчик")
        });
        if (!state.contracts) state.contracts = [];
        state.contracts.unshift(contract);
        toast("Договор создан — редактируй текст");
        save();
        render();
      }

      function quickContractFromDeal(projectId) {
        const proj = projectId
          ? (state.savedProjects || []).find(p => p.id === projectId)
          : null;
        const snap = (proj && proj.snapshot) || {};
        const clientName = (proj ? proj.client : state.project.client) || "Заказчик";
        const projectName = (proj ? proj.name : state.project.name) || "Проект";
        const deadline = (proj ? proj.deadline : state.project.deadline) || "";
        const totalPrice = proj
          ? (proj.total ? String(Math.round(Number(proj.total))) : "___")
          : String(Math.round(totals().total || 0));
        const half = Math.round(Number(totalPrice) / 2) || 0;
        const base = CONTRACT_TEMPLATES[0];
        let body = (base.body || "")
          .replace("[ИСПОЛНИТЕЛЬ]", state.company.name || "Исполнитель")
          .replace("[ЗАКАЗЧИК]", clientName)
          .replace(/_____________________________ \(___________________\) рублей/, `${totalPrice} рублей`)
          .replace(/50% \(_______________\) рублей — в течение 3/g, `50% (${half}) рублей — в течение 3`);
        if (deadline) {
          body = body.replace("«___» ___________ 202__ г.", `до ${deadline}`);
        }
        body = body.replace(/1\.2\. Наименование и формат Результата: _{3,}\./, `1.2. Наименование и формат Результата: ${projectName}.`);
        const contract = normalizeContract({
          name: `${base.name} — ${clientName}`,
          desc: projectName,
          category: base.category || "Видео",
          body
        });
        if (!state.contracts) state.contracts = [];
        state.contracts.unshift(contract);
        if (proj) state.dealModal = null;
        state.contractEditId = contract.id;
        toast("Договор создан с данными сделки");
        save();
        go("contracts");
      }

      function createBlankContract() {
        const contract = normalizeContract({
          name: "Новый договор — " + (state.project.client || state.company.name || ""),
          body: "ДОГОВОР\n\nг. _____________, «___» ___________ 202_ г.\n\n[Исполнитель] и [Заказчик]\n\n1. ПРЕДМЕТ ДОГОВОРА\n\n2. СТОИМОСТЬ И ОПЛАТА\n\n3. СРОКИ\n\n4. ПОДПИСИ\n\nИСПОЛНИТЕЛЬ ________________    ЗАКАЗЧИК ________________"
        });
        if (!state.contracts) state.contracts = [];
        state.contracts.unshift(contract);
        save();
        render();
      }

      function updateContractField(id, key, value) {
        const c = (state.contracts || []).find(x => x.id === id);
        if (c) { c[key] = value; c.updatedAt = new Date().toISOString(); }
        save();
      }

      function deleteContract(id) {
        const idx = (state.contracts || []).findIndex(c => c.id === id);
        if (idx < 0) return;
        const removed = state.contracts[idx];
        state.contracts = state.contracts.filter(c => c.id !== id);
        save();
        render();
        toastUndo("Договор удалён", () => {
          state.contracts.splice(idx, 0, removed);
          save(); render();
          toast("Удаление отменено");
        });
      }

      function printContract(id) {
        const c = (state.contracts || []).find(x => x.id === id);
        if (!c) return;
        const win = window.open("", "_blank");
        if (!win) { toast("❌ Браузер заблокировал открытие окна. Разрешите всплывающие окна для этого сайта."); return; }
        win.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>${escapeHtml(c.name)}</title><style>body{font-family:Arial,sans-serif;margin:40px;line-height:1.6;white-space:pre-wrap;font-size:13px}h1{font-size:18px;margin-bottom:16px}</style></head><body><h1>${escapeHtml(c.name)}</h1>${escapeHtml(c.body)}</body></html>`);
        win.document.close();
        win.print();
      }

      function renderContracts() {
        const contracts = state.contracts || [];
        const editId = state.contractEditId || "";

        if (editId) {
          const c = contracts.find(x => x.id === editId);
          if (c) {
            return `
              <div class="panel">
                <div class="section-title" style="margin-bottom:16px">
                  <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap">
                    <button class="btn small" onclick="app.closeContractEdit()">← Договоры</button>
                    <input value="${escapeHtml(c.name)}" onchange="app.updateContractField('${c.id}','name',this.value)"
                      style="font-size:18px;font-weight:900;background:transparent;border:1px solid transparent;border-radius:8px;padding:4px 8px;color:var(--text);flex:1;min-width:0"
                      onmouseover="this.style.borderColor='var(--line)'" onmouseout="this.style.borderColor='transparent'">
                  </div>
                  <div class="toolbar no-print">
                    <button class="btn green" onclick="app.printContract('${c.id}')">Печать / PDF</button>
                    <button class="btn danger" onclick="app.deleteContract('${c.id}');app.closeContractEdit()">${TRASH_SVG} Удалить</button>
                  </div>
                </div>
                <div class="field" style="margin-bottom:12px">
                  <div class="grid two">
                    ${field("Категория", `<input value="${escapeHtml(c.category||"")}" onchange="app.updateContractField('${c.id}','category',this.value)" placeholder="Видео, Фото...">`)}
                    ${field("Описание", `<input value="${escapeHtml(c.desc||"")}" onchange="app.updateContractField('${c.id}','desc',this.value)" placeholder="Краткое описание">`)}
                    ${field("Клиент", `<select onchange="app.updateContractField('${c.id}','clientId',this.value)">
                      <option value="">— без привязки —</option>
                      ${(state.clients||[]).map(cl => `<option value="${cl.id}" ${c.clientId===cl.id?"selected":""}>${escapeHtml(cl.name)}${cl.company?" · "+escapeHtml(cl.company):""}</option>`).join("")}
                    </select>`)}
                    ${field("Сделка", `<select onchange="app.updateContractField('${c.id}','dealId',this.value)">
                      <option value="">— без привязки —</option>
                      ${(state.savedProjects||[]).map(p => `<option value="${p.id}" ${c.dealId===p.id?"selected":""}>${escapeHtml(p.name)}${p.client?" · "+escapeHtml(p.client):""}</option>`).join("")}
                    </select>`)}
                  </div>
                </div>
                <div class="field">
                  <label style="font-size:12px;color:var(--muted);font-weight:750;margin-bottom:6px;display:block">Текст договора (редактируй свободно)</label>
                  <textarea class="contract-editor" onchange="app.updateContractField('${c.id}','body',this.value)">${escapeHtml(c.body||"")}</textarea>
                </div>
                <p class="mini-note" style="margin-top:8px">Изменения сохраняются автоматически при выходе из поля. Нажми «Печать / PDF» для экспорта.</p>
                <p class="mini-note" style="margin-top:2px">ℹ️ Шаблон носит справочный характер и не является юридической консультацией — перед отправкой клиенту рекомендуем проверить текст у юриста.</p>
              </div>
            `;
          }
        }

        return `
          <div class="panel">
            <div class="section-title">
              <div>
                <h1>Договоры</h1>
                <p>База шаблонов и готовых договоров. Редактируй под каждый проект.</p>
                <p class="mini-note" style="margin-top:4px">ℹ️ Шаблоны носят справочный характер и не являются юридической консультацией — перед использованием с клиентами рекомендуем проверить текст у юриста.</p>
              </div>
              <div class="toolbar no-print">
                ${contracts.length ? `<button class="btn primary" onclick="app.createBlankContract()">+ Пустой договор</button>` : ""}
              </div>
            </div>

            <h2 style="font-size:16px;margin:0 0 12px;color:var(--muted)">Шаблоны</h2>
            <div class="grid four" style="margin-bottom:24px">
              ${CONTRACT_TEMPLATES.map(tpl => `
                <div style="padding:14px;border:1px solid var(--line);border-radius:14px;background:var(--panel2);cursor:pointer;transition:.15s"
                     onclick="app.createContractFromTemplate('${tpl.id}')"
                     onmouseover="this.style.borderColor='rgba(168,85,247,.5)'"
                     onmouseout="this.style.borderColor='var(--line)'">
                  <div style="font-size:20px;margin-bottom:8px">📄</div>
                  <h3 style="font-size:13px;margin:0 0 4px">${escapeHtml(tpl.name)}</h3>
                  <p style="font-size:12px;margin:0">${escapeHtml(tpl.desc)}</p>
                  <span class="badge" style="margin-top:8px;display:inline-flex">${escapeHtml(tpl.category)}</span>
                </div>
              `).join("")}
            </div>

            ${contracts.length ? (() => {
              const cats = ["Все", ...([...new Set(contracts.map(c => c.category || "Прочее"))].sort())];
              const activeCat = state.contractCatFilter || "Все";
              const filtered = activeCat === "Все" ? contracts : contracts.filter(c => (c.category || "Прочее") === activeCat);
              return `
              <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-bottom:12px">
                <h2 style="font-size:16px;margin:0">Мои договоры (${contracts.length})</h2>
                <div style="display:flex;gap:4px;flex-wrap:wrap">
                  ${cats.map(cat => `<button class="badge${activeCat===cat?" active-filter":""}" onclick="app.setContractCatFilter('${escapeHtml(cat)}')"
                    style="cursor:pointer;padding:4px 10px;border-radius:99px;border:1px solid ${activeCat===cat?"var(--primary)":"var(--line)"};background:${activeCat===cat?"var(--primary)":"transparent"};color:${activeCat===cat?"#fff":"var(--muted)"};font-size:12px;font-weight:600">${escapeHtml(cat)}</button>`).join("")}
                </div>
              </div>
              <div class="grid three">
                ${filtered.map(c => `
                  <article class="contract-card" onclick="app.openContractEdit('${c.id}')">
                    <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;margin-bottom:8px">
                      <h3 style="margin:0;font-size:15px">${escapeHtml(c.name)}</h3>
                      <span class="badge">${escapeHtml(c.category||"Прочее")}</span>
                    </div>
                    ${c.desc ? `<p style="font-size:12px;margin:0 0 8px">${escapeHtml(c.desc)}</p>` : ""}
                    <p style="font-size:12px;margin:0;color:var(--muted)">Обновлён: ${formatDate(c.updatedAt)}</p>
                    <div class="toolbar no-print" style="margin-top:10px">
                      <button class="btn small" onclick="event.stopPropagation();app.printContract('${c.id}')">Печать / PDF</button>
                      <button class="btn danger small" onclick="event.stopPropagation();app.deleteContract('${c.id}')">${TRASH_SVG} Удалить</button>
                    </div>
                  </article>
                `).join("")}
              </div>
              ${filtered.length === 0 && activeCat !== "Все" ? emptyState({
                icon: "search",
                title: `Нет договоров в категории «${escapeHtml(activeCat)}»`,
                cta: { label: "Показать все", onclick: "app.setContractCatFilter('Все')", variant: "" }
              }) : ""}
            `;
            })() : emptyState({
              icon: "doc",
              title: "Договоров пока нет",
              text: "Выберите шаблон выше — или начните с пустого договора.",
              cta: { label: "+ Пустой договор", onclick: "app.createBlankContract()" }
            })}
          </div>
        `;
      }

      function setContractCatFilter(cat) {
        state.contractCatFilter = cat;
        render();
      }

      function openContractEdit(id) {
        state.contractEditId = id;
        save();
        render();
      }

      function closeContractEdit() {
        state.contractEditId = "";
        save();
        render();
      }

      function initEvents() {
        // Enter/Space на кликабельных не-кнопках, поднятых в _enhanceA11y.
        // Слушатель ОДИН и делегированный: вешать его в _enhanceA11y значило бы
        // плодить копию на каждый элемент после каждого render().
        // e.target, а не closest(): если фокус стоит на вложенной кнопке карточки,
        // Enter должен нажать кнопку, а не заодно и всю карточку.
        document.addEventListener("keydown", e => {
          if (e.key !== "Enter" && e.key !== " " && e.key !== "Spacebar") return;
          const el = e.target;
          if (!el || !el.hasAttribute || !el.hasAttribute("data-kbd-click")) return;
          e.preventDefault(); // Space иначе прокрутит страницу
          // У SVG-элементов (сегменты графиков) может не быть .click()
          if (typeof el.click === "function") el.click();
          else el.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true }));
        });

        document.querySelectorAll(".nav button").forEach(button => {
          button.addEventListener("click", () => {
            const view = button.dataset.view;
            if (view === "wizard") { startWizard(); return; }
            if (view === "deal") {
              state.dealView = "estimate";
              go("deal");
              return;
            }
            if (view === "clients") { state.clientDetailId = ""; }
            go(view);
          });
        });

        const globalAddBtn = document.getElementById("globalAddBtn");
        if (globalAddBtn) {
          globalAddBtn.addEventListener("click", e => { e.stopPropagation(); toggleGlobalMenu(); });
        }
        document.addEventListener("click", () => { closeGlobalMenu(); closeDealMenu(); closeMobileAddMenu(); closeTagOverflow(); });

        const scrollTopBtn = document.getElementById("scrollTopBtn");
        if (scrollTopBtn) {
          scrollTopBtn.addEventListener("click", () => window.scrollTo({ top: 0, behavior: "smooth" }));
          window.addEventListener("scroll", () => {
            scrollTopBtn.classList.toggle("visible", window.scrollY > 250);
          }, { passive: true });
        }

        document.addEventListener("keydown", e => {
          if ((e.ctrlKey || e.metaKey) && e.key === "z" && !e.shiftKey) {
            const active = document.activeElement;
            if (active && (active.tagName === "INPUT" || active.tagName === "TEXTAREA" || active.tagName === "SELECT")) return;
            e.preventDefault();
            undo();
          }
          if ((e.ctrlKey || e.metaKey) && (e.key === "y" || (e.key === "z" && e.shiftKey))) {
            const active = document.activeElement;
            if (active && (active.tagName === "INPUT" || active.tagName === "TEXTAREA" || active.tagName === "SELECT")) return;
            e.preventDefault();
            redo();
          }
          if ((e.ctrlKey || e.metaKey) && e.key === "k") {
            const active = document.activeElement;
            if (active && (active.tagName === "INPUT" || active.tagName === "TEXTAREA" || active.tagName === "SELECT")) return;
            e.preventDefault();
            openSearch();
          }
          if (e.key === "Escape") {
            closeSearch();
            toggleProfileDd(false);
            toggleHelpDd(false);
            if (state.financeModal) closeFinanceModal();
            else if (state.taskModal) closeTaskModal();
            else if (state.catalogEditId) { state.catalogEditId = ""; renderModal(); }
            else if (state.clientModal) closeClientModal();
            else if (state.dealModal) closeDealModal();
            else if (state.editTransactionModal) closeEditTransactionModal();
            else if (state.packageEditModal) closePackageEditModal();
            else if (state.helpModal) closeHelpModal();
            else if (state.docsModal) closeDocsModal();
            else if (state.mainMenuOpen) { state.mainMenuOpen = false; renderModal(); }
            else if (state.adminModal) closeAdminModal();
            else if (state.briefEditorType) closeBriefEditor();
            else if (state.dealSwitcherOpen) closeDealSwitcher();
          }
          // Ctrl+N — новая сделка (кроме полей ввода)
          if ((e.ctrlKey || e.metaKey) && e.key === "n") {
            const active = document.activeElement;
            if (active && (active.tagName === "INPUT" || active.tagName === "TEXTAREA")) return;
            e.preventDefault();
            startWizard();
          }
          // Ctrl+S — сохранить текущую смету в CRM
          if ((e.ctrlKey || e.metaKey) && e.key === "s") {
            const active = document.activeElement;
            if (active && (active.tagName === "INPUT" || active.tagName === "TEXTAREA")) return;
            e.preventDefault();
            saveCurrentProject();
            toast("Сохранено");
          }
        });

        const themeBtn = document.getElementById("themeBtn");
        if (themeBtn) themeBtn.addEventListener("click", toggleTheme);

        // Смета hover-тултип с именем активного проекта
        const _estimateBtn = document.getElementById("navEstimateBtn");
        const _estimateTip = document.getElementById("estimateNavTooltip");
        if (_estimateBtn && _estimateTip) {
          _estimateBtn.addEventListener("mouseenter", () => {
            const name = _estimateTip.dataset.project;
            if (!name) return;
            _estimateTip.textContent = name;
            const r = _estimateBtn.getBoundingClientRect();
            _estimateTip.style.left = Math.round(r.left) + "px";
            _estimateTip.style.top = Math.round(r.bottom + 8) + "px";
            _estimateTip.classList.add("visible");
          });
          _estimateBtn.addEventListener("mouseleave", () => {
            _estimateTip.classList.remove("visible");
          });
        }

        const clientModeBtn = document.getElementById("clientModeBtn");
        if (clientModeBtn) clientModeBtn.addEventListener("click", toggleClientMode);

        const burgerBtn = document.getElementById("burgerBtn");
        if (burgerBtn) burgerBtn.addEventListener("click", openMainMenu);

        const helpBtn = document.getElementById("helpBtn");
        if (helpBtn) helpBtn.addEventListener("click", openHelpModal);

        const importJsonInput = document.getElementById("importJsonInput");
        if (importJsonInput) importJsonInput.addEventListener("change", importData);

        const importCatalogInput = document.getElementById("importCatalogInput");
        if (importCatalogInput) importCatalogInput.addEventListener("change", importCatalog);

        const importCatalogXlsxInput = document.getElementById("importCatalogXlsxInput");
        if (importCatalogXlsxInput) importCatalogXlsxInput.addEventListener("change", importCatalogXlsx);
      }

      function initTheme() {
        // Встроенный калькулятор (?calc=…, см. adervis.ru/pro/smeta/) живёт в iframe
        // на ЧУЖОМ origin — localStorage хост-страницы ему физически недоступен, поэтому
        // тема хоста передаётся явно параметром ?theme=dark|light в src самого iframe.
        // Без этого калькулятор молча падал на свой собственный дефолт (системная тема
        // браузера) и мог не совпасть с уже выбранной темой сайта — тёмная карточка
        // посреди светлой страницы. localStorage при этом НЕ трогаем (calc-режим его
        // не пишет нигде, см. save()), чтобы тема хоста не просочилась в обычный вход.
        if (_calcMode) {
          const hostTheme = (new URLSearchParams(location.search).get("theme") || "").trim();
          if (hostTheme === "light" || hostTheme === "dark") {
            document.documentElement.setAttribute("data-theme", hostTheme);
            return;
          }
        }

        const savedTheme = lsGet(THEME_KEY);

        if (savedTheme === "light" || savedTheme === "dark") {
          setTheme(savedTheme);
          return;
        }

        const prefersLight = window.matchMedia && window.matchMedia("(prefers-color-scheme: light)").matches;
        setTheme(prefersLight ? "light" : "dark");
      }

